claims.statement:
\begin{convention}
		\label[convention]{con:Categories_And_K_Theory}
		Throughout, \emph{category} means $\infty$-category, and $K$ denotes \emph{nonconnective} algebraic K-theory, regarded as a functor $K\colon \Cat_{\perf} \to \Sp$ on small idempotent complete stable categories. If $C$ is a compactly generated stable category, we often abuse notation and write $K(C) := K(C^{\omega})$.
	\end{convention}

\begin{theorem}[{Lurie, \cite[Proposition~D.7.3.1]{SAG}}]
		\label[theorem]{thm:Dualizable_Characterizations}
		Consider $C \in \PrLst$. The following are equivalent:
		\begin{enumerate}
			\item There exists a localization $\phi\colon D \to E$ in $\PrL_{\omega,\st}$ such that $C = \ker(\phi)$;
			\item $C$ is dualizable in $(\PrLst,\otimes)$;
			\item The functor $\colim\colon \Ind(C) \to C$ has a left adjoint (``compactly assembled'');
			\item $C$ is a retract in $\PrLst$ of a compactly generated category;
			\item (Efimov, \cite[Theorem~5.2]{Efimov_Large_Categories}) $C \otimes (-)\colon \PrLst \to \PrLst$ preserves fully faithful functors (``flat'');
			\item (Clausen--Scholze, see \cite[Proposition~2.51]{Efimov_Large_Categories}) arbitrary products distribute over filtered colimits (``AB6'').
		\end{enumerate}
	\end{theorem}

\begin{example}
		\label[example]{ex:Dualizable_Categories}
		The following categories are dualizable but in general not compactly generated:
		\begin{itemize}
			\item Keller's example of a localization of a compactly generated category with a non-compactly generated kernel (\Cref{ex:Keller});
			\item the category $\Shv(X;\Sp)$ of sheaves of spectra on a locally compact Hausdorff space $X$ (see \Cref{chap:Sheaves}); for instance $\Shv(\R^n;\Sp)$ with $n \geq 1$ has no nonzero compact objects at all (for sheaves of abelian groups on a non-compact connected manifold this is due to Neeman \cite[Theorem~0.1]{Neeman_Sheaves_Manifold}; for sheaves of spectra it follows from Efimov's description of the compact objects \cite[Proposition~10.17]{Efimov_Large_Categories});
			\item the categories of nuclear modules arising in analytic geometry: $\Nuc(\Z_p^{\square})$, $\Nuc(\R^{p\text{-}\mathrm{liq}})$, $\Nuc(\C^{\mathrm{gas}})$ \cite{Scholze_Analytic_Geometry, Clausen_Scholze_Complex_Geometry}.
		\end{itemize}
		The nuclear examples are self-dual because they are \emph{rigid}. Sheaf categories on compact Hausdorff spaces are rigid as well. For general locally compact Hausdorff spaces they are locally rigid, rather than rigid; their self-duality is provided by categorical Verdier duality, see \cite[Section~4.4]{Krause_Nikolaus_Putzstuck_Sheaves} and \Cref{ex:Locally_Rigid_Sheaf_Categories}.
	\end{example}

\begin{definition}[{cf.\ \cite[Chapter~1, Definition~9.1.2]{GaitsgoryRozenbluym2017StudyDAG}}]
		\label[definition]{def:Rigid_Category}
		A \emph{rigid category} is $C \in \CAlg(\PrLst)$ such that for every finite set $I$, the multiplication functor $\mu\colon C^{\otimes I} \to C$ admits a right adjoint in $\Mod_{C^{\otimes I}}(\PrLst)$.
	\end{definition}

\begin{example}
		\label[example]{ex:Rigid_Ind_Categories_Intro}
		Let $C_0$ be a small idempotent complete symmetric monoidal stable category in which every object is dualizable. Then $\Ind(C_0)$ is rigid. For instance, $\D(R) = \Ind(\Perf(R))$ is rigid for every commutative ring $R$.
	\end{example}

\begin{remark}
		\label[remark]{rem:Compact_Objects_And_Morphisms_Intro}
		There is a useful dictionary between the compactly generated and the dualizable world, which will be developed in \Cref{chap:Compact_Morphisms_AB6}: compact \emph{objects} are replaced by compact \emph{morphisms}. A dualizable category is generated under colimits by sequential colimits $\colim(x_0 \to x_1 \to x_2 \to \cdots)$ along compact morphisms, and in fact its $\omega_1$-compact objects are precisely of this form. In a symmetric monoidal setting, the analogy continues: just as a compactly generated category with compact unit is rigid if its compact objects are precisely its dualizable objects, a dualizable symmetric monoidal category is rigid if its compact morphisms are precisely its trace-class morphisms.
	\end{remark}

\begin{definition}
		\label[definition]{def:Cat_Dual}
		We denote by
		\[
			\Pr^{\dual} \subseteq \PrLst
		\]
		the subcategory consisting of the dualizable categories and the strongly continuous functors, i.e.\ those functors whose right adjoint again preserves colimits (see \Cref{def:Dualizable_Category}).
	\end{definition}

\begin{definition}
		\label[definition]{def:Continuous_Extension}
		Let $F$ be a localizing invariant. Then we define
		\[
			F^{\cont}(C) := \fib\big(F(C^{\kappa}) \to F(\Calk^{\cont}_{\kappa}(C))\big)
		\]
		for $\kappa = \omega_1$. When $F$ is K-theory, $K^{\cont}(C)$ is called the \emph{continuous K-theory} of $C$.
	\end{definition}

\begin{example}
		\label[example]{ex:THH_Categorical_Trace}
		The continuous extension of $\THH$ admits a very clean description: it is the \emph{categorical trace}
		\[
			\THH\colon \Pr^{\dual} \to \Sp, \qquad C \mapsto \tr(\id_C) \in \End_{\PrLst}(\Sp) = \Sp,
		\]
		also known as the dimension of $C$ as a dualizable object of $\PrLst$. That this is a localizing invariant is a formal property of traces.
	\end{example}

\begin{example}
		\label[example]{ex:Kcont_Euclidean_Sheaves}
		Taking $X = \R^n$, we get $K^{\cont}(\Shv(\R^n;C)) \simeq \Omega^n K^{\cont}(C)$. In particular, the higher K-groups of $C$ can be recovered as Grothendieck groups:
		\[
			K^{\cont}_n(C) \cong K^{\cont}_0(\Shv(\R^n;C)).
		\]
	\end{example}

\begin{example}
		\label[example]{ex:Compact_Operators_Intro}
		By a theorem of Wodzicki, if $A$ is a unital C$^*$-algebra and $I \subseteq A$ a closed two-sided ideal, then $A \to A/I$ is idempotent. Applying this to $A = B(\Hh)$ and $I = \Kk$, we get a dualizable category $\D(\Kk) := \D(B(\Hh) \to B(\Hh)/\Kk)$, and
		\[
			K^{\cont}(\D(\Kk)) \simeq \fib\big(K(B(\Hh)) \to K(B(\Hh)/\Kk)\big) = K(\Kk) \simeq \KU.
		\]
		So this is the category we were looking for in \Cref{sec:Small_Categories_Fall_Short}! Since $K(B(\Hh)) = 0$ by an Eilenberg swindle, $K^{\cont}(\D(\Kk))$ is the loop spectrum of the K-theory of the \emph{Calkin algebra} $B(\Hh)/\Kk$; this is the origin of the name ``Calkin category''.

		According to Clausen \citep{Clausen_Efimov_K_Theory_Lecture_2}, there is an intrinsic model of $\D(\Kk)$ in terms of separable complex Hilbert spaces. One forms formal sequential colimits along compact operators and then closes under colimits and shifts in both directions. In this model the completed Hilbert tensor product induces the multiplication on continuous K-theory.
	\end{example}

\begin{theorem}[{Andreychev, \cite[Satz~4.2 and Satz~5.12]{Andreychev_Thesis}}]
		\label[theorem]{thm:Nuclear_Analytic_Descent}
		Let $(A,A^+)$ be a complete sheafy analytic Huber pair. The assignments $U \mapsto \Nuc(\mathcal{O}(U))$ and $U \mapsto K^{\cont}(\Nuc(\mathcal{O}(U)))$, for $U \subseteq \operatorname{Spa}(A,A^+)$ rational open, satisfy descent for covers by rational open subsets.
	\end{theorem}

\begin{theorem}[{\cite[Theorem~I.3.3]{NikolausScholze2018Cyclic}}]
		\label[theorem]{thm:Verdier_Quotient}
		Let $B$ be a small stable category and $A \subseteq B$ a full stable subcategory. Let $W_A$ be the class of morphisms of $B$ whose cofiber lies in $A$, and let $q\colon B \to B/A := B[W_A^{-1}]$ be the localization. Then:
		\begin{enumerate}
			\item The category $B/A$ is stable and $q$ is exact.
			\item For every stable category $E$, restriction along $q$ induces an equivalence between $\Fun^{\ex}(B/A,E)$ and the full subcategory of $\Fun^{\ex}(B,E)$ spanned by the functors that vanish on $A$.
			\item For $x,y \in B$, the category $A_{/y}$ is filtered and
			\[
				\Map_{B/A}(qx,qy) \simeq \colim_{(a \to y) \in A_{/y}} \Map_B\big(x,\cofib(a \to y)\big).
			\]
		\end{enumerate}
		The category $B/A$ is called the \emph{Verdier quotient} of $B$ by $A$.
	\end{theorem}

\begin{lemma}
		\label[lemma]{lem:Kernel_Verdier_Quotient}
		In the situation of \Cref{thm:Verdier_Quotient}, the kernel of $q\colon B \to B/A$ is the thick closure of $A$ in $B$, i.e.\ the full subcategory of retracts of objects of $A$. In particular, $B/A \simeq B/\bar{A}$, where $\bar{A}$ is the thick closure of $A$.
	\end{lemma}

proofs.text:
\begin{proof}
		Since $q$ is exact, its kernel is a thick subcategory of $B$, and it contains $A$ since $0 \to a$ lies in $W_A$ for $a \in A$. Conversely, let $x \in B$ with $q(x) \simeq 0$. Then $\id_{qx}$ is nullhomotopic, so by \Cref{thm:Verdier_Quotient}(3) (applied with $y = x$) there exists $a \to x$ with $a \in A$ such that the canonical map $x \to c := \cofib(a \to x)$ is nullhomotopic. Since $a \simeq \fib(x \to c)$ and the fiber of a nullhomotopic map $x \to c$ is $x \oplus \Omega c$, it follows that $x$ is a retract of $a$. This shows that the kernel of $q$ consists of retracts of objects of $A$, and every retract of an object of $A$ lies in the thick subcategory $\ker(q)$. The last statement follows from the universal property \Cref{thm:Verdier_Quotient}(2), since an exact functor vanishes on $A$ if and only if it vanishes on $\bar{A}$.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Nullhomotopies_Property}
		Let $F\colon B \to C$ be a functor into a pointed category $C$. Since the constant functor $0$ with value a zero object is a terminal object of $\Fun(B,C)$, the space of natural transformations $F \to 0$ is contractible. Hence the space of equivalences $F \simeq 0$ is either empty or contractible, and it is non-empty if and only if $F$ sends every object to a zero object. So for a composable pair $A \xrightarrow{i} B \xrightarrow{p} C$ of functors between pointed categories, a nullhomotopy $pi \simeq 0$ is unique if it exists, and its existence is a \emph{property} of the pair $(i,p)$. We will therefore write ``$pi \simeq 0$'' as a condition throughout, without specifying a nullhomotopy.
	\end{remark}

\begin{definition}
		\label[definition]{def:Verdier_Sequence}
		A sequence $A \xrightarrow{i} B \xrightarrow{p} C$ in $\Cat_{\st}$ with $pi \simeq 0$ is called a \emph{Verdier sequence} if it is both a fiber sequence and a cofiber sequence in $\Cat_{\st}$. Explicitly, this means that $i$ is fully faithful with essential image $\ker(p)$, and that the induced functor $B/A \to C$ is an equivalence. In this case $p$ is called a \emph{Verdier projection}.
	\end{definition}

\begin{definition}
		\label[definition]{def:Short_Exact_Sequence}
		A sequence $A \xrightarrow{i} B \xrightarrow{p} C$ in $\Cat_{\perf}$ with $pi \simeq 0$ is called a \emph{short exact sequence} (or \emph{Karoubi sequence}) if it is both a fiber sequence and a cofiber sequence in $\Cat_{\perf}$. Explicitly, this means that $i$ is fully faithful with essential image $\ker(p)$, and that the induced functor $(B/A)^{\idem} \to C$ is an equivalence. In this case $p$ is called a \emph{Karoubi projection}.
	\end{definition}

\begin{lemma}
		\label[lemma]{lem:Characterization_Short_Exact}
		A sequence $A \xrightarrow{i} B \xrightarrow{p} C$ in $\Cat_{\perf}$ with $pi \simeq 0$ is short exact if and only if $i$ is fully faithful with essential image $\ker(p)$, the induced functor $B/A \to C$ is fully faithful, and every object of $C$ is a retract of an object in the image of $p$.
	\end{lemma}

proofs.text:
\begin{proof}
		The functor $\bar{p}\colon B/A \to C$ factors as $B/A \hookrightarrow (B/A)^{\idem} \to C$. If $\bar{p}$ is fully faithful, then so is $(B/A)^{\idem} \to C$, since mapping spaces between retracts of objects are retracts of mapping spaces between those objects. If moreover every object of $C$ is a retract of an object $p(b) = \bar{p}(qb)$, then $(B/A)^{\idem} \to C$ is essentially surjective since $(B/A)^{\idem}$ is idempotent complete. Conversely, if $(B/A)^{\idem} \to C$ is an equivalence, then $\bar{p}$ is fully faithful and every object of $C$ is a retract of an object of $B/A$, and hence of an object $p(b)$, as $q$ is essentially surjective.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Verdier_Vs_Karoubi}
		Every Verdier sequence between idempotent complete categories is short exact. The converse fails whenever $A \subseteq B$ is a thick subcategory such that the Verdier quotient $B/A$ is not idempotent complete: then $A \to B \to (B/A)^{\idem}$ is short exact but not a Verdier sequence.
	\end{remark}

\begin{remark}
		\label[remark]{rem:Mapping_Spectra_Quotient}
		Let $A \subseteq B$ be a full stable subcategory with quotient functor $q\colon B \to B/A$. Applying \Cref{thm:Verdier_Quotient}(3) to all shifts of $x$, and using that the colimit is filtered and hence commutes with cofibers, we obtain the following formula for the mapping spectra:
		\begin{align*}
			\hom_{B/A}(qx,qy) &\simeq \colim_{(a \to y) \in A_{/y}} \hom_B\big(x,\cofib(a \to y)\big) \\
			&\simeq \cofib\Big(\colim_{(a \to y) \in A_{/y}} \hom_B(x,a) \to \hom_B(x,y)\Big).
		\end{align*}
		Since $B/A \to (B/A)^{\idem}$ is fully faithful, the same formula computes mapping spectra in the idempotent complete quotient.
	\end{remark}

\begin{remark}
		\label[remark]{rem:Lifting_Objects_Quotient}
		In a short exact sequence $A \to B \xrightarrow{p} C$, the functor $p$ need not be essentially surjective: in general, objects of $C$ are only retracts of objects in the image of $p$. It is possible to say precisely which objects lift. By Thomason's classification of dense subcategories \cite{Thomason_Classification}, the essential image of the dense subcategory $B/A \subseteq C$ consists precisely of those objects $c \in C$ whose class $[c] \in K_0(C)$ lies in the image of $K_0(B) \to K_0(C)$. For example, $c \oplus \Sigma c$ always lifts to $B$, since $[c \oplus \Sigma c] = [c] - [c] = 0$.
	\end{remark}

\begin{definition}
		\label[definition]{def:Localization_Sequence_PrL}
		A sequence $K \xrightarrow{i} D \xrightarrow{p} E$ in $\PrL_{\st}$ with $pi \simeq 0$ is called a \emph{localization sequence} if $i$ is fully faithful with essential image $\ker(p)$ and $p$ is a \emph{localization}, i.e.\ its right adjoint $p^R$ is fully faithful. It is called \emph{strongly continuous} if moreover $i$ and $p$ are strongly continuous.
	\end{definition}

\begin{proposition}
		\label[proposition]{prop:Localization_Sequences_PrL}
		\leavevmode
		\begin{enumerate}
			\item Let $D$ be a presentable stable category and $K \subseteq D$ a full stable subcategory which is closed under colimits and presentable. Then the inclusion $i\colon K \hookrightarrow D$ has a right adjoint $i^R$, the full subcategory $K^{\perp} \subseteq D$ is presentable, its inclusion admits a left adjoint $L\colon D \to K^{\perp}$ given by
			\[
				L(x) = \cofib(ii^R x \to x),
			\]
			and $K \xrightarrow{i} D \xrightarrow{L} K^{\perp}$ is a localization sequence. It is both a fiber sequence and a cofiber sequence in $\PrL_{\st}$.
			\item Conversely, let $K \xrightarrow{i} D \xrightarrow{p} E$ be a localization sequence. Then $p^R$ induces an equivalence $E \simeq K^{\perp}$ under which $p$ corresponds to $L$, and there is a natural cofiber sequence
			\[
				ii^R \to \id_D \to p^Rp.
			\]
		\end{enumerate}
	\end{proposition}

proofs.text:
\begin{proof}
		(1) The inclusion $i$ preserves colimits, so it has a right adjoint by \Cref{thm:Adjoint_Functor_Theorem}. Define $L(x) = \cofib(ii^Rx \to x)$, using the counit. For $k \in K$, the map $\hom_D(k,ii^Rx) \to \hom_D(k,x)$ is an equivalence since $i$ is fully faithful, so $\hom_D(k,L(x)) \simeq 0$; that is, $L(x) \in K^{\perp}$. For $y \in K^{\perp}$, applying $\hom_D(-,y)$ to the cofiber sequence $ii^Rx \to x \to L(x)$ shows that $\hom_D(L(x),y) \to \hom_D(x,y)$ is an equivalence, since $\hom_D(ii^Rx,y) \simeq 0$. Hence $L\colon D \to K^{\perp}$ is left adjoint to the inclusion $K^{\perp} \subseteq D$, with unit $x \to L(x)$. The functor $L$ is accessible since $i^R$ is (being a right adjoint between presentable categories), so $K^{\perp}$ is presentable \cite[Section~5.5.4]{lurie2009HTT}. Since its right adjoint is fully faithful, $L$ is a localization, and $L(x) \simeq 0$ if and only if $ii^Rx \to x$ is an equivalence, if and only if $x \in K$. This shows that $K \to D \to K^{\perp}$ is a localization sequence. It is a fiber sequence in $\PrL_{\st}$ since limits in $\PrL$ are computed in $\widehat{\Cat}$. For the cofiber sequence, let $F\colon D \to E$ be a colimit-preserving functor to a presentable stable category $E$. Since $L$ is a localization, restriction along $L$ identifies $\Fun^{\colim}(K^{\perp},E)$ with the full subcategory of $\Fun^{\colim}(D,E)$ of functors inverting the maps $x \to x'$ with $L(x) \simeq L(x')$. Since $L$ is exact, these are precisely the maps whose fiber lies in $\ker(L) = K$, and an exact functor inverts all such maps if and only if it vanishes on $K$. This is precisely the universal property of the cofiber of $i$ in $\PrL_{\st}$.

		(2) Since $p^R$ is fully faithful and $\Map_D(k,p^Re) \simeq \Map_E(pk,e) \simeq *$ for $k \in K$, the functor $p^R$ lands in $K^{\perp}$. Conversely, let $x \in K^{\perp}$ and let $f \to x \to p^Rp(x)$ be the fiber sequence of the unit. As $pp^R \simeq \id$, we have $p(f) \simeq 0$, so $f \in K$. Then $\hom_D(f,x) \simeq 0$ and $\hom_D(f,p^Rpx) \simeq \hom_E(pf,px) \simeq 0$, so $\hom_D(f,f) \simeq 0$ and hence $f \simeq 0$. So $x \simeq p^Rp(x)$, which shows that $p^R$ induces an equivalence $E \simeq K^{\perp}$. Under this equivalence, $p$ is identified with the left adjoint $L$ of the inclusion $K^{\perp} \subseteq D$, and the unit $x \to p^Rp(x) = L(x)$ is the cofiber of $ii^Rx \to x$ by (1).
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Strong_Continuity_Localization_Sequence}
		Let $K \xrightarrow{i} D \xrightarrow{p} E$ be a localization sequence. Then $i^R$ preserves colimits if and only if $p^R$ preserves colimits. In particular, the sequence is strongly continuous as soon as $i$ or $p$ is strongly continuous.
	\end{lemma}

proofs.text:
\begin{proof}
		Since $i$ is fully faithful and preserves colimits, $i^R$ preserves colimits if and only if $ii^R$ does: indeed, for a diagram $(x_j)$ the map $i(\colim_j i^Rx_j) \simeq \colim_j ii^Rx_j \to ii^R(\colim_j x_j)$ is the image under $i$ of the comparison map for $i^R$. Similarly, $p^R$ preserves colimits if and only if $p^Rp$ does: if $p^Rp$ preserves colimits and $(e_j)$ is a diagram in $E$, then $\colim_j e_j \simeq p(\colim_j p^Re_j)$, so $p^R(\colim_j e_j) \simeq p^Rp(\colim_j p^Re_j) \simeq \colim_j p^Rpp^Re_j \simeq \colim_j p^Re_j$. Finally, by \Cref{prop:Localization_Sequences_PrL}(2) there is a cofiber sequence of exact functors $ii^R \to \id \to p^Rp$, so $ii^R$ preserves colimits if and only if $p^Rp$ does.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Compact_Generators_Thick_Closure}
		Let $E$ be a presentable stable category and $G \subseteq E^{\omega}$ a set of compact objects such that $\hom_E(g,e) \simeq 0$ for all $g \in G$ implies $e \simeq 0$. Then $E^{\omega}$ is the thick closure of $G$, and $E \simeq \Ind(E^{\omega})$.
	\end{lemma}

proofs.text:
\begin{proof}
		Let $T \subseteq E^{\omega}$ be the thick closure of $G$; it is essentially small. The functor $\Ind(T) \to E$ extending the inclusion is fully faithful since $T$ consists of compact objects, and its essential image is closed under colimits since $T$ is closed under finite colimits \cite[Section~5.3.5]{lurie2009HTT}. Its right adjoint is conservative: if $\hom_E(t,e) \simeq 0$ for all $t \in T$ then $e \simeq 0$ by assumption. Hence $\Ind(T) \simeq E$. Since $T$ is idempotent complete, the compact objects of $\Ind(T)$ are precisely the objects of $T$ (\Cref{thm:Accessible_Recollections}(1)), so $E^{\omega} = T$.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Compact_Objects_Localization_Sequence}
		Let $K \xrightarrow{i} D \xrightarrow{p} E$ be a strongly continuous localization sequence. Then $i$ and $p$ preserve compact objects, and $K^{\omega} = K \cap D^{\omega}$. If $D$ is compactly generated, then so is $E$, and $E^{\omega}$ is the thick closure of $p(D^{\omega})$.
	\end{lemma}

proofs.text:
\begin{proof}
		A colimit-preserving functor whose right adjoint preserves filtered colimits preserves compact objects. If $k \in K$ is compact in $D$, then it is compact in $K$ since $i$ is fully faithful and preserves colimits. If $D$ is compactly generated and $e \in E$ satisfies $\hom_E(p(d),e) \simeq \hom_D(d,p^Re) \simeq 0$ for all $d \in D^{\omega}$, then $p^Re \simeq 0$ and hence $e \simeq pp^Re \simeq 0$. The claim follows from \Cref{lem:Compact_Generators_Thick_Closure}.
	\end{proof}

claims.statement:
\begin{definition}[{\cite[Definition~1.9]{Efimov_Large_Categories}}]
		\label[definition]{def:Homological_Epimorphism}
		A functor $f\colon A \to B$ in $\Cat_{\perf}$ is called a \emph{homological epimorphism} if $\Ind(f)\colon \Ind(A) \to \Ind(B)$ is a localization, i.e.\ its right adjoint is fully faithful.
	\end{definition}

\begin{theorem}[Thomason--Neeman]
		\label[theorem]{thm:Thomason_Neeman}
		\leavevmode
		\begin{enumerate}
			\item If $A \xrightarrow{i} B \xrightarrow{p} C$ is a short exact sequence in $\Cat_{\perf}$, then $\Ind(A) \to \Ind(B) \to \Ind(C)$ is a strongly continuous localization sequence. In particular, every Karoubi projection is a homological epimorphism.
			\item Conversely, if $K \xrightarrow{i} D \xrightarrow{p} E$ is a strongly continuous localization sequence in which $K$ and $D$ are compactly generated, then $E$ is compactly generated and $K^{\omega} \to D^{\omega} \to E^{\omega}$ is a short exact sequence.
		\end{enumerate}
	\end{theorem}

proofs.text:
\begin{proof}
		(1) The functor $\Ind(i)$ is fully faithful, as mapping spaces between ind-objects are computed by the formula of \Cref{constr:Ind_Large}. Its essential image $K \subseteq \Ind(B)$ is closed under colimits and presentable, so by \Cref{prop:Localization_Sequences_PrL}(1) we obtain a localization sequence $K \to \Ind(B) \xrightarrow{L} K^{\perp}$ which is a cofiber sequence in $\PrL_{\st}$. For every presentable stable category $E$, we have natural equivalences
		\[
			\begin{aligned}
				\Fun^{\colim}(K^{\perp},E) &\simeq \Fun^{\colim}_{K \mapsto 0}(\Ind(B),E) \simeq \Fun^{\ex}_{A \mapsto 0}(B,E) \\
				&\simeq \Fun^{\ex}(B/A,E) \simeq \Fun^{\ex}((B/A)^{\idem},E) \simeq \Fun^{\colim}(\Ind(C),E),
			\end{aligned}
		\]
		using \Cref{thm:Ind_Kappa_Universal_Property}(3), \Cref{thm:Verdier_Quotient}(2), the fact that $E$ is idempotent complete, and $(B/A)^{\idem} \simeq C$. Under these equivalences, precomposition with $L$ corresponds to precomposition with $\Ind(p)$. By the Yoneda lemma there is an equivalence $K^{\perp} \simeq \Ind(C)$ under which $L$ corresponds to $\Ind(p)$. Hence $\Ind(A) \to \Ind(B) \to \Ind(C)$ is a localization sequence. Since $\Ind(i)$ preserves compact objects, its right adjoint preserves filtered colimits, hence all colimits; so the sequence is strongly continuous by \Cref{lem:Strong_Continuity_Localization_Sequence}.

		(2) Put $A = K^{\omega}$ and $B = D^{\omega}$. By \Cref{lem:Compact_Objects_Localization_Sequence}, $i$ restricts to a fully faithful functor $A \to B$ whose image $A = K \cap B$ is a thick subcategory of $B$. By \Cref{lem:Kernel_Verdier_Quotient}, the sequence $A \to B \to (B/A)^{\idem}$ is short exact, so by (1) we obtain a localization sequence $\Ind(A) \to \Ind(B) \to \Ind((B/A)^{\idem})$. As $K \simeq \Ind(A)$ and $D \simeq \Ind(B)$, both $E$ and $\Ind((B/A)^{\idem})$ are identified with $K^{\perp}$ compatibly with the functors from $D$, by \Cref{prop:Localization_Sequences_PrL}(2). Hence $E \simeq \Ind((B/A)^{\idem})$ is compactly generated with $E^{\omega} \simeq (B/A)^{\idem}$, and the claim follows.
	\end{proof}

claims.statement:
\begin{corollary}
		\label[corollary]{cor:Karoubi_Quotient_Via_Ind}
		Let $i\colon A \hookrightarrow B$ be a fully faithful functor in $\Cat_{\perf}$. Under the identification $\Ind(-) \simeq \Fun^{\ex}((-)\catop,\Sp)$, the right adjoint $\Ind(i)^R\colon \Ind(B) \to \Ind(A)$ is given by restriction along $i$, and
		\[
			(B/A)^{\idem} \simeq \ker\big(\Ind(i)^R\big)^{\omega},
		\]
		where $\ker(\Ind(i)^R) \subseteq \Fun^{\ex}(B\catop,\Sp)$ is the full subcategory of exact functors vanishing on $A$.
	\end{corollary}

proofs.text:
\begin{proof}
		For $a \in A$ and $F \in \Ind(B)$ we have $\hom_{\Ind(A)}(a,\Ind(i)^RF) \simeq \hom_{\Ind(B)}(ia,F) \simeq F(ia)$ by the Yoneda lemma, so $\Ind(i)^R(F) \simeq F \circ i\catop$. Since $A$ is idempotent complete and $i$ is fully faithful, the essential image of $i$ is a thick subcategory, so $A \to B \to (B/A)^{\idem}$ is short exact by \Cref{lem:Kernel_Verdier_Quotient}. By \Cref{thm:Thomason_Neeman}(1), $\Ind(A) \to \Ind(B) \to \Ind((B/A)^{\idem})$ is a localization sequence, so by \Cref{prop:Localization_Sequences_PrL}(2) we have $\Ind((B/A)^{\idem}) \simeq \Ind(A)^{\perp}$. Finally, $F \in \Ind(A)^{\perp}$ if and only if $\hom(a,\Ind(i)^RF) \simeq \hom(ia,F) \simeq 0$ for all $a \in A$, if and only if $\Ind(i)^RF \simeq 0$. Taking compact objects gives the claim.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Ind_Fully_Faithful_Localization}
		The functor $\Ind$ induces an equivalence of categories
		\[
			\Ind\colon \Cat_{\perf} \rightleftarrows \PrL_{\omega,\st}\noloc (-)^{\omega},
		\]
		where $\PrL_{\omega,\st}$ denotes the category of compactly generated presentable stable categories and colimit-preserving functors that preserve compact objects (equivalently, strongly continuous functors), see \Cref{thm:Accessible_Recollections} and \Cref{lem:Compact_Generators_Thick_Closure}. For a functor $f\colon A \to B$ in $\Cat_{\perf}$:
		\begin{itemize}
			\item $f$ is fully faithful if and only if $\Ind(f)$ is fully faithful (by the formula for mapping spaces in \Cref{constr:Ind_Large}), if and only if $\Ind(f)$ is a monomorphism \cite[Proposition~1.13]{Efimov_Large_Categories};
			\item If $f$ is a Karoubi projection, then $\Ind(f)$ is a localization (\Cref{thm:Thomason_Neeman}), or equivalently $\Ind(f)$ is an epimorphism \cite[Proposition~1.13]{Efimov_Large_Categories}. The converse does not hold, see \Cref{ex:Keller}.
		\end{itemize}
	\end{remark}

\begin{definition}[{\cite[Definition~2.74]{Efimov_Large_Categories}}]
		\label[definition]{def:Semiorthogonal_Decomposition}
		A \emph{semiorthogonal decomposition} of a presentable stable category $E$ is a collection of full presentable stable subcategories $C_1,\dots,C_n \subseteq E$ such that
		\begin{enumerate}
			\item the inclusion functors $C_i \hookrightarrow E$ are strongly continuous;
			\item for $i > j$, $x \in C_i$ and $y \in C_j$ we have $\hom_E(x,y) \simeq 0$;
			\item the smallest full stable subcategory of $E$ containing $C_1,\dots,C_n$ is $E$ itself.
		\end{enumerate}
		In this case we write $E = \lra{C_1,\dots,C_n}$.
	\end{definition}

\begin{proposition}
		\label[proposition]{prop:Two_Term_SOD}
		Let $E = \lra{C,D}$ be a semiorthogonal decomposition, with inclusions $i_C\colon C \hookrightarrow E$ and $i_D\colon D \hookrightarrow E$. Then:
		\begin{enumerate}
			\item Every $x \in E$ fits into a cofiber sequence $d \to x \to c$ with $d \in D$ and $c \in C$, which is unique up to unique equivalence and functorial in $x$.
			\item The functor $i_C$ admits a left adjoint $i_C^L$ and $i_D$ admits a right adjoint $i_D^R$, given by $x \mapsto c$ and $x \mapsto d$ respectively; there is a natural cofiber sequence $i_Di_D^R \to \id_E \to i_Ci_C^L$, and $i_C^Li_D \simeq 0$.
			\item The sequence $D \xrightarrow{i_D} E \xrightarrow{i_C^L} C$ is a strongly continuous localization sequence, split by $i_C$.
		\end{enumerate}
	\end{proposition}

proofs.text:
\begin{proof}
		Note first that $\hom_E(d,c) \simeq 0$ for $d \in D$ and $c \in C$. Suppose $d \to x \to c$ is a cofiber sequence with $d \in D$ and $c \in C$. For $d' \in D$ we then have $\hom_E(d',d) \xrightarrow{\simeq} \hom_E(d',x)$, since $\hom_E(d',c) \simeq 0$; so $d \to x$ exhibits $d$ as the value at $x$ of a right adjoint to $i_D$. Dually, for $c' \in C$ we have $\hom_E(c,c') \xrightarrow{\simeq} \hom_E(x,c')$, so $x \to c$ exhibits $c$ as the value at $x$ of a left adjoint of $i_C$. In particular, such a sequence is unique up to unique equivalence and functorial in $x$, wherever it exists.

		Let $E' \subseteq E$ be the full subcategory of those $x$ that admit such a cofiber sequence. It contains $C$ (take $0 \to c \to c$) and $D$ (take $d \to d \to 0$) and is closed under shifts. It is closed under cofibers: a map $x \to x'$ in $E'$ induces, by the universal properties above, a map of cofiber sequences, and passing to cofibers gives a cofiber sequence $\cofib(d \to d') \to \cofib(x \to x') \to \cofib(c \to c')$ with first term in $D$ and last term in $C$, as these are stable subcategories. Hence $E'$ is a stable subcategory containing $C$ and $D$, so $E' = E$ by assumption (3). This proves (1), and by \cite[Proposition~5.2.4.2]{lurie2009HTT} also the existence of the adjoints in (2), together with the cofiber sequence $i_Di_D^R \to \id \to i_Ci_C^L$. Applying it to $x = i_D(d)$ gives $i_C^Li_D(d) \simeq 0$.

		For (3), $i_C^L$ is a localization since its right adjoint $i_C$ is fully faithful, and $i_C^L(x) \simeq 0$ if and only if $i_Di_D^R x \to x$ is an equivalence, if and only if $x$ lies in the essential image of $D$. The right adjoints $i_D^R$ and $i_C$ preserve colimits by assumption (1) and since $C \subseteq E$ is closed under colimits, so the sequence is strongly continuous. Finally, $i_C^L i_C \simeq \id_C$ as $i_C$ is fully faithful, so $i_C$ splits $i_C^L$.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Remark~2.75]{Efimov_Large_Categories}}]
		\label[proposition]{prop:SOD_Characterization}
		Let $i_1\colon C \to E$ and $i_2\colon D \to E$ be strongly continuous functors between presentable stable categories. Then $i_1$ and $i_2$ are fully faithful and exhibit $E = \lra{i_1(C), i_2(D)}$ as a semiorthogonal decomposition if and only if the following conditions hold:
		\begin{enumerate}
			\item $i_1$ admits a left adjoint $i_1^L$ and $i_2$ admits a right adjoint $i_2^R$;
			\item the counit $i_1^Li_1 \to \id_C$ and the unit $\id_D \to i_2^Ri_2$ are equivalences;
			\item $i_1^Li_2 \simeq 0$, or equivalently $i_2^Ri_1 \simeq 0$;
			\item the sequence $i_2i_2^R \to \id_E \to i_1i_1^L$, formed by the counit and the unit, is a cofiber sequence.
		\end{enumerate}
		In this case, the functors $i_1^L$ and $i_2^R$ are strongly continuous.
	\end{proposition}

\begin{remark}
		\label[remark]{rem:SOD_Small}
		\Cref{def:Semiorthogonal_Decomposition} makes sense for any stable category $E$ and full stable subcategories $C_1,\dots,C_n \subseteq E$, omitting condition (1). No presentability or size assumption is needed. Parts (1) and (2) of \Cref{prop:Two_Term_SOD} hold in this setting with the same proof, and the sequence $D \xrightarrow{i_D} E \xrightarrow{i_C^L} C$ is a Verdier sequence: $i_C^L$ is a localization with kernel $D$, and it inverts precisely the maps whose cofiber lies in $D$. If $E$ is idempotent complete, then so are $C$ and $D$, being thick subcategories of $E$ (as kernels of the exact functors $i_D^R$ and $i_C^L$), and the sequence is short exact. (In the talk, the definition was given simultaneously for presentable stable categories, for dualizable categories and for small stable categories.)
	\end{remark}

\begin{proposition}
		\label[proposition]{prop:SOD_From_Short_Exact}
		Let $A \xrightarrow{i} B \xrightarrow{p} C$ be a short exact sequence in $\Cat_{\perf}$. Then $i$ admits a right adjoint $i^R$ if and only if $p$ admits a right adjoint $p^R$. In this case:
		\begin{enumerate}
			\item The functor $p^R$ is fully faithful, with essential image the right orthogonal $A^{\perp} = \{x \in B \mid \hom_B(ia,x) \simeq 0 \text{ for all } a \in A\}$;
			\item There is a semiorthogonal decomposition $B = \lra{p^R(C),\, i(A)}$;
			\item The sequence $C \xrightarrow{p^R} B \xrightarrow{i^R} A$ is again short exact.
		\end{enumerate}
	\end{proposition}

\begin{definition}
		\label[definition]{def:K_0}
		The \emph{Grothendieck group} $K_0(A)$ of a small stable category $A$ is the free abelian group on the equivalence classes $[x]$ of objects $x \in A$, modulo the relations $[x] = [x'] + [x'']$ for every cofiber sequence $x' \to x \to x''$ in $A$.
	\end{definition}

\begin{definition}
		\label[definition]{def:Localizing_Invariant}
		Let $\Ee$ be a stable category. A functor $F\colon \Cat_{\perf} \to \Ee$ is called a \emph{localizing invariant} if $F(0) \simeq 0$ and $F$ sends short exact sequences (\Cref{def:Short_Exact_Sequence}) to fiber sequences. We extend $F$ to $\Cat_{\st}$ by setting $F(A) := F(A^{\idem})$. We denote by $\Fun_{\loc}(\Cat_{\st},\Ee)$ the full subcategory of localizing invariants.
	\end{definition}

\begin{lemma}
		\label[lemma]{lem:Localizing_Invariants_Verdier}
		Let $\Ee$ be stable and let $F\colon \Cat_{\st} \to \Ee$ satisfy $F(0) \simeq 0$. Consider the following conditions:
		\begin{enumerate}
			\item For every Verdier sequence $A \hookrightarrow B \to B/A$ in the sense of \Cref{def:Verdier_Sequence}, $F$ takes this sequence to a fiber sequence.
			\item Each sequence $A \hookrightarrow B \to C$ with $A \to B$ fully faithful and inducing an equivalence $(B/A)^{\idem} \iso C^{\idem}$ is sent to a fiber sequence under $F$.
		\end{enumerate}
		Then (2) implies (1), and (2) holds if and only if $F$ satisfies (1) and inverts the maps $A \to A^{\idem}$. In this case, $F$ is (the extension of) a localizing invariant in the sense of \Cref{def:Localizing_Invariant}.
	\end{lemma}

proofs.text:
\begin{proof}
		The sequences in (1) are among those of (2). Suppose that $F$ satisfies (1) and inverts idempotent completions. For a sequence as in (2), the fully faithful functor $A^{\idem} \hookrightarrow B^{\idem}$ has thick image, so
		\[
			A^{\idem} \hookrightarrow B^{\idem} \to B^{\idem}/A^{\idem}
		\]
		is a Verdier sequence. Moreover, $(B^{\idem}/A^{\idem})^{\idem} \simeq (B/A)^{\idem} \simeq C^{\idem}$, by the universal property of the idempotent complete quotient. Applying (1) and idempotent invariance therefore gives (2). Conversely, (2) applied to $0 \to A \to A^{\idem}$ shows that $F(A) \to F(A^{\idem})$ is an isomorphism.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Verdier_Localizing_Not_Karoubi}
		Condition (1) of \Cref{lem:Localizing_Invariants_Verdier} alone does not imply that $F$ inverts $A \to A^{\idem}$. For instance, connective algebraic K-theory satisfies (1) (see the proof of \cite[Corollary~4.4.15]{Hermitian_II}), but $K_0(A) \to K_0(A^{\idem})$ is in general not surjective. This is why localizing invariants are defined on idempotent complete categories.
	\end{remark}

\begin{remark}
		\label[remark]{rem:Finitary_Localizing_Invariants}
		One frequently additionally requires that $\Ee$ is presentable and that $F$ preserves filtered colimits (or at least $\kappa$-filtered colimits for some regular cardinal $\kappa$). Algebraic K-theory and $\THH$ are examples of localizing invariants preserving filtered colimits. Topological cyclic homology $\mathrm{TC}$ is localizing, but does not in general preserve filtered colimits.
	\end{remark}

\begin{example}
		\label[example]{ex:Localizing_Additive}
		Let $B = \lra{C,D}$ be a semiorthogonal decomposition in $\Cat_{\perf}$ (\Cref{rem:SOD_Small}). Then every localizing invariant $F$ sends the short exact sequence $D \to B \to C$ to a fiber sequence $F(D) \to F(B) \to F(C)$, which is split by $F(i_C)$. Hence
		\[
			F(B) \simeq F(C) \oplus F(D).
		\]
		Functors $F\colon \Cat_{\perf} \to \Ee$ with this property are called \emph{additive}.
	\end{example}

\begin{theorem}
		\label[theorem]{thm:K_Universal_Property}
		Nonconnective algebraic K-theory $K\colon \Cat_{\perf} \to \Sp$ is the initial localizing invariant equipped with a natural transformation $(-)^{\simeq} \to \Omega^{\infty}K(-)$.
	\end{theorem}

\begin{remark}
		\label[remark]{rem:K_Universal_Property_Literature}
		In the literature, \Cref{thm:K_Universal_Property} is usually stated for localizing invariants preserving filtered colimits, see \cite{BGT2013Universal} and also \cite{Barwick_Higher_K_Theory}. The version without this condition is explicitly stated in \cite[page~115, footnote~19]{Ramzi_Thesis}. That footnote does not supply a proof of the additional generality.
	\end{remark}

\begin{definition}[{\cite{BGT2013Universal}}]
		\label[definition]{def:Mot_Loc}
		The category of \emph{localizing motives} $\mathrm{Mot}_{\loc}$ is the presentable stable category equipped with a localizing invariant
		\[
			U_{\loc}\colon \Cat_{\perf} \to \mathrm{Mot}_{\loc}
		\]
		preserving filtered colimits, characterized as follows: for every presentable stable category $\Ee$, precomposition with $U_{\loc}$ induces an equivalence between colimit-preserving functors $\mathrm{Mot}_{\loc}\to\Ee$ and localizing invariants $\Cat_{\perf}\to\Ee$ preserving filtered colimits. We fix a universe for the small categories in $\Cat_{\perf}$ and use a larger universe for functor categories; these size conventions are suppressed in the notation.
	\end{definition}

\begin{theorem}[{Theorem/definition, cf.\ \cite{BGT2013Universal}}]
		\label[theorem]{thm:K_Unit_Day_Convolution}
		$K$ is the unit for the Day convolution operad structure on $\Fun_{\loc}(\Cat_{\perf},\Sp)$, where localizing invariants are not required to preserve filtered colimits.
	\end{theorem}

\begin{theorem}[{Tamme, before Efimov, \cite[Theorem~18]{Tamme_Excision}}]
		\label[theorem]{thm:Tamme_Excision}
		Consider a square $Q$ in $\Cat_{\st}$ of the form
		\[
			\begin{tikzcd}
				A \rar["f"] \dar & B \dar \\
				C \rar["g"'] & D.
			\end{tikzcd}
		\]
		Assume that $\Ind(Q)$ is cartesian, and that $\Ind(f)$ and $\Ind(g)$ are localizations. Then every localizing invariant $F$ sends $Q$ to a cartesian square.
	\end{theorem}

\begin{warning}
		\label[warning]{warn:Excision_Requires_Ind_Localizations}
		One cannot simply apply $F$ to the common kernel of $f$ and $g$. The hypotheses say that $\Ind(f)$ and $\Ind(g)$ are localizations; they do not say that $f$ and $g$ are Karoubi projections. Their small kernels therefore need not give short exact sequences to which $F$ applies.
	\end{warning}

\begin{remark}
		\label[remark]{rem:Tamme_Lax_Pullback_Proof}
		Tamme's original proof predates continuous K-theory and applies to localizing invariants with values in any stable category, without accessibility assumptions. It uses the lax pullback $P = B \times_D^{\to} C$ of triples $(b,c,\varphi\colon h(b) \to g(c))$, where $h\colon B \to D$ is the right vertical functor. There is a split exact sequence $C \to P \to B$ \cite[Proposition~10]{Tamme_Excision}, and under the hypotheses of \Cref{thm:Tamme_Excision} the functor $(b,c,\varphi) \mapsto \cofib(\varphi)$ fits into an exact sequence $A \to P \to D$ \cite[Theorem~15]{Tamme_Excision}. Comparing the two sequences gives the claim. See \cite{Land_Tamme_Pullbacks} for a generalization to arbitrary pullbacks of ring spectra.
	\end{remark}

\begin{example}[{Milnor patching, \cite{Milnor_Intro_K_Theory}}]
		\label[example]{ex:Milnor_Patching}
		Consider a pullback square of $\bbE_1$-rings:
		\[
			\begin{tikzcd}
				A \rar \dar & A' \dar \\
				B \rar & B'
			\end{tikzcd}
		\]
		and assume that $A' \otimes_A A' \iso A'$. Then the induced square
		\[
			\begin{tikzcd}
				\Mod_A \rar \dar & \Mod_{A'} \dar \\
				\Mod_B \rar & \Mod_{B'}
			\end{tikzcd}
		\]
		is also a pullback square, and $\Mod_B \to \Mod_{B'}$ is a localization \cite[Lemma~23 and Theorem~26]{Tamme_Excision}. In particular, we deduce:
	\end{example}

\begin{theorem}[{\cite[Theorem~28]{Tamme_Excision}; see also \cite{Land_Tamme_Pullbacks}}]
		\label[theorem]{thm:Milnor_Patching_K_Theory}
		In the above situation, there is a pullback square
		\[
			\begin{tikzcd}
				K(A) \rar \dar & K(A') \dar \\
				K(B) \rar & K(B').
			\end{tikzcd}
		\]
	\end{theorem}

\begin{example}
		\label[example]{ex:Milnor_Square_Of_Rings}
		Given a map of rings $A \to B$ that sends an ideal $I \subseteq A$ isomorphically to the induced ideal $IB \subseteq B$, the induced square
		\[
			\begin{tikzcd}
				A \rar \dar & A/I \dar \\
				B \rar & B/IB
			\end{tikzcd}
		\]
		is a pullback of $\bbE_1$-rings.
	\end{example}

\begin{definition}
		\label[definition]{def:Compactly_Assembled}
		A category $C$ is called \emph{compactly assembled} if it is accessible, admits filtered colimits, and the colimit functor $\colim\colon \Ind(C) \to C$ admits a left adjoint $\hat{y}\colon C \hookrightarrow \Ind(C)$.
	\end{definition}

\begin{lemma}
		\label[lemma]{lem:Compact_Iff_Yhat_Is_Y}
		Let $C$ be compactly assembled and $x \in C$. Then $x$ is compact if and only if the map $\hat{y}(x) \to y(x)$ is an equivalence.
	\end{lemma}

\begin{remark}
		\label[remark]{rem:Compact_Morphisms_Ideal}
		Compact morphisms form a two-sided ideal: if $f\colon x \to x'$ is compact and $k\colon w \to x$ and $h\colon x' \to x''$ are arbitrary, then $hfk$ is compact. Indeed, given a factorization $\theta\colon \Map_C(x',\colim(-)) \to \Map_{\Ind(C)}(y(x),-)$ of $f^*$, the composite $y(k)^* \circ \theta \circ h^*$ is a factorization of $(hfk)^* = k^*f^*h^*$.
	\end{remark}

\begin{lemma}
		\label[lemma]{lem:Compact_Morphisms_Yhat}
		Let $C$ be compactly assembled and let $f\colon x \to x'$ be a morphism in $C$.
		\begin{enumerate}
			\item The morphism $f$ is compact if and only if $y(f)\colon y(x) \to y(x')$ factors through the map $\hat{y}(x') \to y(x')$.
			\item The identity $\id_x$ is a compact morphism if and only if $x$ is a compact object.
		\end{enumerate}
	\end{lemma}

proofs.text:
\begin{proof}
		(1) Write $\varepsilon\colon \hat{y}(x') \to y(x')$, and recall that $\colim(\varepsilon)$ is the identity of $x'$. By the adjunction $\hat{y} \dashv \colim$, we have $\Map_C(x',\colim(-)) \simeq \Map_{\Ind(C)}(\hat{y}(x'),-)$, so by the Yoneda lemma, natural transformations $\theta\colon \Map_C(x',\colim(-)) \to \Map_{\Ind(C)}(y(x),-)$ correspond to maps $g\colon y(x) \to \hat{y}(x')$, via $\theta = g^*$. The composite of $g^*$ with the transformation $\Map_{\Ind(C)}(y(x),-) \to \Map_C(x,\colim(-))$ is precomposition with $\colim(g)\colon x \to x'$. Hence $f$ is compact if and only if there is a map $g\colon y(x) \to \hat{y}(x')$ with $\colim(g) \simeq f$. If $\varepsilon g \simeq y(f)$, then $\colim(g) \simeq \colim(\varepsilon g) \simeq f$. Conversely, if $\colim(g) \simeq f$, then $\varepsilon g$ and $y(f)$ are maps $y(x) \to y(x')$ with the same image under $\colim$; since $\colim\colon \Map_{\Ind(C)}(y(x),y(x')) \to \Map_C(x,x')$ is inverse to the equivalence induced by the fully faithful functor $y$, we get $\varepsilon g \simeq y(f)$.

		(2) By (1), $\id_x$ is compact if and only if $\varepsilon\colon \hat{y}(x) \to y(x)$ admits a section $g$. In that case, $g\varepsilon\colon \hat{y}(x) \to \hat{y}(x)$ corresponds under the adjunction to $\colim(g)\colon x \to x$, which is the identity since $\colim(\varepsilon g) = \id_x$ and $\colim(\varepsilon) = \id_x$. Hence $g\varepsilon \simeq \id$, so $\varepsilon$ is an equivalence and $x$ is compact by \Cref{lem:Compact_Iff_Yhat_Is_Y}. The converse is clear.
	\end{proof}

claims.statement:
\begin{example}
		\label[example]{ex:Compactly_Generated_Compactly_Assembled}
		If $C$ is accessible and compactly generated, then $C$ is compactly assembled. Indeed, if $C = \Ind(C_0)$ with $C_0$ small, then
		\[
			\hat{y} = \Ind(y_{C_0})\colon \Ind(C_0) \to \Ind(\Ind(C_0)),
		\]
		where $y_{C_0}\colon C_0 \hookrightarrow \Ind(C_0) = C$ is the Yoneda embedding. When $C$ is cocomplete, we may take $C_0=C^{\omega}$ by \href{https://animarium.org/tag/01BJ/}{[SHT, Proposition~23.3.7]}.
	\end{example}

\begin{example}[{Continuous posets, \cite{Johnstone_Joyal_Continuous_Categories, Gierz_Continuous_Lattices}}]
		\label[example]{ex:Continuous_Posets}
		Let $P$ be a partially ordered set admitting directed joins, regarded as a category. Then $\Ind(P)$ is the poset of \emph{ideals} of $P$, i.e.\ non-empty directed downward closed subsets $I \subseteq P$, ordered by inclusion, and $\colim\colon \Ind(P) \to P$ sends $I$ to its join $\bigvee I$. The functor $y$ sends $x$ to the principal ideal ${\downarrow}x$, which is the largest ideal with join $\leq x$. A left adjoint $\hat{y}$, if it exists, sends $x$ to the smallest ideal $I$ with $x \leq \bigvee I$.

		Say that $y$ is \emph{way below} $x$, written $y \ll x$, if $y \in I$ for every ideal $I$ with $x \leq \bigvee I$; taking $I = {\downarrow}x$ shows that $y \ll x$ implies $y \leq x$. Then $\hat{y}$ exists if and only if for every $x \in P$ the set ${\downarrow\!\!\downarrow}x = \{y \in P \mid y \ll x\}$ is directed with join $x$, in which case $\hat{y}(x) = {\downarrow\!\!\downarrow}x$; we prove this in \Cref{prop:Continuous_Poset_Characterization}. Posets with this property are classically called \emph{continuous}. An element $x$ is compact if and only if $x \ll x$, in accordance with \Cref{lem:Compact_Iff_Yhat_Is_Y}. For example:
		\begin{enumerate}
			\item In the interval $[0,1]$, we have $y \ll x$ if and only if $y < x$ or $y = 0$. So $[0,1]$ is continuous, and its only compact element is $0$.
			\item Let $X$ be a locally compact Hausdorff space and let $\mathrm{Open}(X)$ be the poset of open subsets. Then $U \ll V$ if and only if there exists a compact subset $K \subseteq X$ with $U \subseteq K \subseteq V$, and $\mathrm{Open}(X)$ is continuous. The compact elements are the compact open subsets; for $X = \R^n$ the only one is $\emptyset$.
			\item The power set of a set $S$ is continuous, and in fact \emph{algebraic}, i.e.\ compactly generated: the compact elements are the finite subsets, and every subset is the directed union of its finite subsets.
		\end{enumerate}
		Note how example (2) foreshadows the fact that $\Shv(\R^n;\Sp)$ is dualizable but has no nonzero compact objects. Continuous posets are discussed in more detail, with proofs, in \Cref{sec:Continuous_Posets}.
	\end{example}

\begin{theorem}[{Lurie, \cite[Definition~21.1.2.1 and Theorem~21.1.2.10]{SAG}}]
		\label[theorem]{thm:Compactly_Assembled_Retract}
		Let $C$ be a category with filtered colimits. Then the following are equivalent:
		\begin{enumerate}
			\item $C$ is compactly assembled;
			\item There exists a small category $D$ such that $C$ is a retract of $\Ind(D)$ as a category with filtered colimits.
		\end{enumerate}
	\end{theorem}

\begin{definition}
		\label[definition]{def:Strongly_Continuous_Compactly_Assembled}
		Let $C$ and $D$ be compactly assembled. A functor $f\colon C \to D$ is called \emph{strongly continuous} if it preserves filtered colimits and commutes with $\hat{y}$, meaning that the mate transformation
		\[
			\hat{y}_D f \to \Ind(f) \hat{y}_C
		\]
		of the commutative square
		\[
			\begin{tikzcd}
				\Ind(C) \rar["\colim_C"] \dar["\Ind(f)"'] & C \dar["f"] \\
				\Ind(D) \rar["\colim_D"'] & D
			\end{tikzcd}
		\]
		is a natural isomorphism.
	\end{definition}

\begin{remark}
		\label[remark]{rem:Strongly_Continuous_Right_Adjoint}
		Assume $f$ admits a right adjoint $g\colon D \to C$. Then the condition that $f$ is strongly continuous is equivalent to $g$ preserving filtered colimits, see \Cref{prop:Strongly_Continuous_Via_Right_Adjoint}.
	\end{remark}

\begin{definition}
		\label[definition]{def:Dualizable_Category}
		A \emph{dualizable category} is a dualizable object of $\PrL_{\st}$. We denote by $\Pr^{\dual} \subseteq \PrL_{\st}$ the subcategory whose objects are the dualizable categories and whose morphisms are the internal left adjoints, i.e.\ those functors in $\PrL_{\st}$ whose right adjoint also lies in $\PrL_{\st}$, i.e.\ preserves colimits.
	\end{definition}

\begin{example}
		\label[example]{ex:Dual_Of_Modules}
		Let $A$ be an $\bbE_1$-ring and let $\Mod_A$ denote the category of right $A$-modules, so that $\Mod_A \simeq \Ind(\Perf_A)$. Then $\Mod_A$ is dualizable with dual $\Mod_{A\catop}$, the category of left $A$-modules. The evaluation and coevaluation are given by
		\begin{alignat*}{2}
			\ev&\colon \Mod_A \otimes \Mod_{A\catop} \to \Sp, &\qquad (M,N) &\mapsto M \otimes_A N, \\
			\coev&\colon \Sp \to \Mod_{A\catop} \otimes \Mod_A \simeq \mathrm{BMod}_{A,A}, &\qquad \S &\mapsto A,
		\end{alignat*}
		where the coevaluation sends the sphere spectrum to $A$ regarded as an $A$-bimodule. This is a special case of \Cref{cor:Compactly_Generated_Dualizable}, using the equivalence $\Perf_A\catop \simeq \Perf_{A\catop}$, $P \mapsto \hom_A(P,A)$.
	\end{example}

\begin{remark}
		\label[remark]{rem:Strongly_Continuous_Stable}
		Note that a right adjoint of a functor between stable categories automatically preserves finite colimits, so it preserves all colimits if and only if it preserves filtered colimits. So the morphisms in $\Pr^{\dual}$ are precisely the strongly continuous functors.
	\end{remark}

\begin{remark}
		\label[remark]{rem:Compactly_Generated_In_Prdual}
		By \Cref{cor:Compactly_Generated_Dualizable}, every compactly generated category $C = \Ind(C_0)$ is dualizable. Moreover, every colimit-preserving functor preserving compact objects is strongly continuous, so a morphism in $\Pr^{\dual}$ by \Cref{rem:Strongly_Continuous_Stable}. So we get a fully faithful inclusion
		\[
			\PrL_{\omega,\st} \subseteq \Pr^{\dual}.
		\]
	\end{remark}

\begin{remark}
		\label[remark]{rem:Prdual_Formal_Properties}
		Dualizable objects of a symmetric monoidal category are closed under tensor products, and the tensor product of two strongly continuous functors is again strongly continuous: since $- \otimes D$ is a functor of $(\infty,2)$-categories, it preserves adjunctions, so the right adjoint of $f \otimes D$ is $f^R \otimes D$, which again preserves colimits. Hence the symmetric monoidal structure on $\PrL_{\st}$ restricts to $\Pr^{\dual}$. Moreover, the inclusion $\Pr^{\dual} \hookrightarrow \PrL_{\st}$ preserves colimits (\Cref{prop:Prdual_Colimits}), and $\Pr^{\dual}$ admits all limits, although these are \emph{not} computed in $\PrL_{\st}$; see \Cref{thm:General_Limits_Dualizable}.
	\end{remark}

\begin{theorem}[{Lurie, \cite[Proposition~D.7.3.1]{SAG}}]
		\label[theorem]{thm:Lurie_Dualizable_Characterization}
		Let $C \in \PrL_{\st}$. Then the following are equivalent:
		\begin{enumerate}
			\item $C$ is dualizable;
			\item $C$ is compactly assembled;
			\item There exists a localization $D \to E$ in $\PrL_{\omega,\st}$ such that $C = \ker(D \to E)$;
			\item $C$ has the left lifting property with respect to any localization in $\PrL_{\st}$: for every localization $D \to E$ and any $C \to E$, there exists a lift $C \to D$:
			\[
				\begin{tikzcd}
					& D \dar \\
					C \rar \arrow[ur, dashed] & E.
				\end{tikzcd}
			\]
		\end{enumerate}
	\end{theorem}

\begin{proposition}
		\label[proposition]{prop:Dualizable_Further_Characterizations}
		Let $C \in \PrL_{\st}$. Then the following are equivalent:
		\begin{enumerate}
			\item $C$ is dualizable;
			\item The functor $\colim\colon \Ind(C) \to C$ preserves small products;
			\item For every regular cardinal $\kappa$ such that $C$ is $\kappa$-compactly generated, the functor $\colim\colon \Ind(C^{\kappa}) \to C$ admits a left adjoint;
			\item There exist a regular cardinal $\kappa$ such that $C$ is $\kappa$-compactly generated and the functor $\colim\colon \Ind(C^{\kappa}) \to C$ admits a left adjoint;
			\item There exists a fully faithful strongly continuous functor $C \hookrightarrow D$ into a compactly generated category $D$.
		\end{enumerate}
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Further_Characterizations_Later}
		Further characterizations of dualizable categories will be given later in these notes:
		\begin{itemize}
			\item $C$ is equivalent to $\ker(\Mod_A \to \Mod_B)$ for a homological epimorphism of $\bbE_1$-rings $A \to B$ (\Cref{chap:Examples});
			\item $C$ is generated under colimits by \emph{compactly exhaustible} objects, i.e.\ sequential colimits along compact morphisms (\Cref{prop:Dualizable_Compactly_Exhaustible});
			\item $C$ satisfies (AB6), i.e.\ filtered colimits distribute over products in $C$; this is an elementwise reformulation of condition (2) of \Cref{prop:Dualizable_Further_Characterizations} (\Cref{prop:Dualizable_AB6});
			\item $C$ is \emph{flat}, i.e.\ $C \otimes -$ preserves fully faithful functors in $\PrL_{\st}$ (\Cref{chap:Flatness}).
		\end{itemize}
	\end{remark}

\begin{proposition}[Localization sequences of dualizable categories]
		\label[proposition]{prop:Localization_Sequence_Dualizable}
		Let $K \xrightarrow{i} D \xrightarrow{p} E$ be a strongly continuous localization sequence in $\PrL_{\st}$ (\Cref{def:Localization_Sequence_PrL}). If $D$ is dualizable, then so are $K$ and $E$, and the sequence is a sequence in $\Pr^{\dual}$.
	\end{proposition}

proofs.text:
\begin{proof}
		Since $i$ and $p^R$ are fully faithful, we have $i^Ri \simeq \id_K$ and $pp^R \simeq \id_E$. By strong continuity, $i^R$ and $p^R$ preserve colimits, so $K$ and $E$ are retracts of $D$ in $\PrL_{\st}$, hence dualizable. The functors $i$ and $p$ are strongly continuous by assumption.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Omega_1_Compact_Compact_Morphisms}
		By \Cref{lem:Compact_Morphisms_Yhat}, the condition on the transition maps in \Cref{thm:Compactly_Assembled_Omega_1}(2) says precisely that the maps $x_n \to x_{n+1}$ are compact morphisms. So the $\omega_1$-compact objects of a compactly assembled category are precisely the sequential colimits along compact morphisms, and every object is an $\omega_1$-filtered colimit of such. In \Cref{chap:Compact_Morphisms_AB6} we will see that, conversely, a presentable stable category is dualizable if and only if it is generated under colimits by such sequential colimits. While compact \emph{objects} are the right tool to study compactly generated categories, compact \emph{morphisms} are the right tool to study dualizable ones.
	\end{remark}

\begin{proposition}
		\label[proposition]{prop:Strongly_Continuous_Compact_Morphisms}
		Let $F\colon C \to D$ be a colimit-preserving functor between dualizable categories. Then $F$ is strongly continuous if and only if $F$ preserves compact morphisms.
	\end{proposition}

\begin{definition}[{\cite[Definition~2.2.3]{Krause_Nikolaus_Putzstuck_Sheaves}}]
		\label[definition]{def:Weakly_Compact_Morphism}
		Let $C$ be a category with filtered colimits. A morphism $f\colon x \to x'$ in $C$ is called \emph{weakly compact} if for every filtered diagram $(z_i)_{i \in I}$ in $C$ and every morphism $g\colon x' \to \colim_i z_i$, the composite $gf\colon x \to \colim_i z_i$ factors through the canonical map $z_i \to \colim_i z_i$ for some $i \in I$.
	\end{definition}

\begin{remark}
		\label[remark]{rem:Weakly_Compact_Lifting}
		Since $y(x)$ is compact in $\Ind(C)$, maps $y(x) \to \quotcolim_i z_i$ are the same as maps $x \to z_i$ for some $i$, up to the usual identifications. Hence $f$ is weakly compact if and only if for every $Z \in \Ind(C)$, every diagram of solid arrows
		\[
			\begin{tikzcd}
				y(x) \rar[dashed] \dar["y(f)"'] & Z \dar["\eta_Z"] \\
				y(x') \rar & y(\colim Z)
			\end{tikzcd}
		\]
		admits a dashed arrow making the square commute. Here $\eta_Z$ is the unit of the adjunction $\colim \dashv y$ of \Cref{constr:Ind_Large}, and a map $y(x') \to y(\colim Z)$ is the same as a map $x' \to \colim Z$, since $y$ is fully faithful.

		A compact morphism in the sense of \Cref{def:Compact_Morphism} is weakly compact: the factorization of $f^*$ through $\Map_{\Ind(C)}(y(x),-)$ provides, in particular, a lift of each point. In the terminology of \cite[Definition~2.2.4]{Krause_Nikolaus_Putzstuck_Sheaves}, compact morphisms in our sense are called \emph{strongly compact}.
	\end{remark}

\begin{example}
		\label[example]{ex:Weakly_Compact_Basic}
		\leavevmode
		\begin{enumerate}
			\item If $x$ is compact, then $\id_x$ is weakly compact. The converse holds for stable $C$, see \Cref{cor:Compact_Iff_Identity_Weakly_Compact} below.
			\item As in \Cref{rem:Compact_Morphisms_Ideal}, weakly compact morphisms form a two-sided ideal: if $f\colon x \to x'$ is weakly compact and $k\colon w \to x$, $h\colon x' \to x''$ are arbitrary, then for every $g\colon x'' \to \colim_i z_i$ the composite $(gh)f$ factors through some $z_i$, and hence so does $ghfk$.
			\item In particular, every morphism which factors through a compact object is weakly compact.
		\end{enumerate}
	\end{example}

\begin{proposition}[{\cite[Proposition~2.39]{Efimov_Large_Categories}, \cite[Proposition~2.4.1]{Krause_Nikolaus_Putzstuck_Sheaves}}]
		\label[proposition]{prop:Compact_Morphism_Characterizations}
		Let $C$ be compactly assembled and let $f\colon x \to x'$ be a morphism in $C$. Then the following are equivalent:
		\begin{enumerate}
			\item $f$ is compact (in the sense of \Cref{def:Compact_Morphism});
			\item $f$ is weakly compact;
			\item $y(f)\colon y(x) \to y(x')$ factors through $\varepsilon_{x'}\colon \hat{y}(x') \to y(x')$;
			\item $\hat{y}(f)\colon \hat{y}(x) \to \hat{y}(x')$ factors through $\varepsilon_x\colon \hat{y}(x) \to y(x)$;
			\item $\hat{y}(f)$ is a weakly compact morphism in $\Ind(C)$.
		\end{enumerate}
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Weak_Compactness_In_Small_Ind_Categories}
		In (5), weak compactness in $\Ind(C)$ may be replaced by weak compactness in $\Ind(C^{\kappa})$, for any $\kappa$ such that $\hat{y}$ takes values in $\Ind(C^{\kappa})$, by the same argument. In particular, if $C$ is dualizable we may take $\kappa = \omega_1$ (\Cref{thm:Compactly_Assembled_Omega_1}), and then $\Ind(C^{\omega_1})$ is compactly generated.
	\end{remark}

\begin{corollary}[{\cite[Corollary~2.40]{Efimov_Large_Categories}, \cite[Proposition~2.4.4]{Krause_Nikolaus_Putzstuck_Sheaves}}]
		\label[corollary]{cor:Compact_Morphism_Factorization}
		Let $C$ be compactly assembled. Then every compact morphism $f\colon x \to x'$ factors as a composite $x \xrightarrow{f_1} w \xrightarrow{f_2} x'$ of two compact morphisms.
	\end{corollary}

\begin{lemma}
		\label[lemma]{lem:Interpolation}
		Let $D$ be a category, let $S$ be a class of morphisms of $D$ which is closed under homotopy and composition, and let $P$ be a class of objects of $D$. Assume that every morphism in $S$ is homotopic to a composite $x \to p \to x'$ of two morphisms in $S$ with $p \in P$.
		\begin{enumerate}
			\item For every morphism $s\colon x \to x'$ in $S$ there is a functor $F\colon \Q_{[0,1]} \to D$ with $F(0) = x$, $F(1) = x'$ and $F(0 \leq 1) \simeq s$, such that $F(a \leq b) \in S$ for all $a < b$ and $F(a) \in P$ for all $0 < a < 1$.
			\item For every sequence $x_0 \to x_1 \to x_2 \to \cdots$ of morphisms in $S$ there is a functor $F\colon \Q_{\geq 0} \to D$ whose restriction to $\N \subseteq \Q_{\geq 0}$ is equivalent to the given sequence, such that $F(a \leq b) \in S$ for all $a < b$ and $F(a) \in P$ for all $a \notin \N$. If $D$ admits sequential colimits, then $\colim_{\Q_{\geq 0}} F \simeq \colim_n x_n$.
		\end{enumerate}
	\end{lemma}

proofs.text:
\begin{proof}
		(1) The set $T$ of dyadic rationals in $[0,1]$ is a countable dense totally ordered set with a smallest and a largest element, so it is order-isomorphic to $\Q_{[0,1]}$ by Cantor's back-and-forth argument; we may therefore replace $\Q_{[0,1]}$ by $T$, with $0$ and $1$ preserved. Let $T_k = \{i/2^k \mid 0 \leq i \leq 2^k\}$, so that $T = \bigcup_k T_k$ and hence $N(T) = \bigcup_k N(T_k)$. Thus $\Fun(T,D) \simeq \lim_k \Fun(T_k,D)$, and on cores this is a limit of a tower of animae. So it suffices to construct functors $F_k\colon T_k \to D$, with $F_k(a \leq b) \in S$ for $a < b$ and $F_k(a) \in P$ for $0 < a < 1$, together with equivalences $F_{k+1}|_{T_k} \simeq F_k$. Indeed, a point of the limit of a tower of animae is specified by points at each stage and paths between their successive images; no separate higher compatibility choices are required. As in \Cref{rem:Sequential_Diagrams}, a functor out of a finite totally ordered set amounts to a composable sequence of morphisms, and two such functors are equivalent as soon as they agree on objects and their consecutive morphisms are homotopic. Let $F_0$ be given by $s$. Given $F_k$, factor each morphism $F_k(a \leq a')$ between consecutive elements $a < a'$ of $T_k$ as a composite of two morphisms in $S$ through an object of $P$, and let $F_{k+1}$ be the resulting functor on $T_{k+1}$. Then $F_{k+1}|_{T_k}$ and $F_k$ agree on objects, and their consecutive morphisms are homotopic, so $F_{k+1}|_{T_k} \simeq F_k$. Since $S$ is closed under composition, every $F_{k+1}(a \leq b)$ with $a < b$ is in $S$.

		(2) Apply the construction of (1) simultaneously to all morphisms $x_n \to x_{n+1}$: on the dyadic rationals in $[0,\infty)$, which are the union of the subsets $2^{-k}\N$, we refine the given sequence on $\N = 2^{0}\N$ by factoring consecutive morphisms as before. The set of dyadic rationals in $[0,\infty)$ is order-isomorphic to $\Q_{\geq 0}$ by an isomorphism fixing $\N$ (apply the back-and-forth argument to each interval $[n,n+1]$). Finally, $\N \subseteq \Q_{\geq 0}$ is cofinal, so the colimits agree by \Cref{lem:Cofinality_Posets}.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Propositions~2.4.4 and~2.4.6]{Krause_Nikolaus_Putzstuck_Sheaves}}]
		\label[proposition]{prop:Compact_Interpolation}
		Let $C$ be compactly assembled.
		\begin{enumerate}
			\item Every compact morphism $f\colon x \to x'$ factors as $x \to w \to x'$ with both morphisms compact and $w$ an $\omega_1$-compact object.
			\item Every compact morphism $f\colon x \to x'$ extends to a functor $F\colon \Q_{[0,1]} \to C$ with $F(0 \leq 1) \simeq f$, such that $F(a \leq b)$ is compact for all $a < b$ and $F(a)$ is $\omega_1$-compact for $0 < a < 1$.
			\item An object of $C$ is $\omega_1$-compact if and only if it is the colimit of a functor $F\colon \Q_{\geq 0} \to C$, or equivalently of a functor $F\colon \Q \to C$, such that $F(a \leq b)$ is compact for all $a < b$. Moreover, $F$ can be chosen to take values in $\omega_1$-compact objects.
		\end{enumerate}
	\end{proposition}

proofs.text:
\begin{proof}
		(1) By \Cref{cor:Compact_Morphism_Factorization}, applied twice, $f$ factors as $x \to x_0 \to x_0' \to x'$ with all three maps compact. By \Cref{thm:Compactly_Assembled_Omega_1}(1), $x_0'$ is a filtered colimit of $\omega_1$-compact objects, so the compact (hence weakly compact, by \Cref{prop:Compact_Morphism_Characterizations}) morphism $x_0 \to x_0'$ factors as $x_0 \to w \to x_0'$ with $w$ $\omega_1$-compact. Since compact morphisms form an ideal, $x \to x_0 \to w$ and $w \to x_0' \to x'$ are compact.

		(2) Apply \Cref{lem:Interpolation}(1) to the class $S$ of compact morphisms and the class $P$ of $\omega_1$-compact objects, using (1).

		(3) By \Cref{thm:Compactly_Assembled_Omega_1}(2), \Cref{rem:Omega_1_Compact_Compact_Morphisms} and \Cref{prop:Compact_Morphism_Characterizations}, an object $x$ is $\omega_1$-compact if and only if $x \simeq \colim_n x_n$ for a sequence of compact morphisms $x_n \to x_{n+1}$. By (1), each $x_n \to x_{n+1}$ factors as $x_n \to w_n \to x_{n+1}$ through an $\omega_1$-compact $w_n$, with both maps compact. The sequence $w_0 \to w_1 \to \cdots$ of composites $w_n \to x_{n+1} \to w_{n+1}$ again consists of compact morphisms between $\omega_1$-compact objects, and has colimit $x$ by cofinality. Applying \Cref{lem:Interpolation}(2) to it (with $P$ the $\omega_1$-compact objects) gives a functor $F\colon \Q_{\geq 0} \to C$ with the required properties and colimit $x$. Since $\Q_{> 0} \subseteq \Q_{\geq 0}$ is cofinal and $\Q_{> 0}$ is order-isomorphic to $\Q$ (both are countable dense totally ordered sets without endpoints), we may equivalently use $\Q$. Conversely, the colimit of such a functor is the colimit of its restriction to the cofinal subset $\N$, which is $\omega_1$-compact by \Cref{thm:Compactly_Assembled_Omega_1}(2).
	\end{proof}

claims.statement:
\begin{proposition}
		\label[proposition]{prop:Compact_Morphisms_Stable}
		Let $C$ be a stable category with filtered colimits (e.g.\ $C \in \PrL_{\st}$), and let $f\colon x \to x'$ be a morphism in $C$. Then $f$ is weakly compact if and only if for every $Z \in \Ind(C)$ with $\colim Z \simeq 0$, the map
		\[
			f^*\colon \pi_0\Map_{\Ind(C)}(y(x'),Z) \to \pi_0\Map_{\Ind(C)}(y(x),Z)
		\]
		is zero. Explicitly, this means: for every filtered diagram $(z_i)_{i \in I}$ with $\colim_i z_i \simeq 0$ and every map $g\colon x' \to z_i$, there is $i' \geq i$ such that the composite $x \xrightarrow{f} x' \xrightarrow{g} z_i \to z_{i'}$ is nullhomotopic.
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Compact_Morphisms_Other_Definitions}
		In the literature one also finds weaker, ``elementwise'' definitions of compact morphisms. For instance, Clausen and Mathew call a morphism $f\colon x \to x'$ in a presentable stable category compact if for every filtered diagram $(z_j)_j$ with $\colim_j z_j \simeq 0$, every map $x' \to z_j$ becomes nullhomotopic after precomposition with $f$ and postcomposition with $z_j \to z_{j'}$ for some $j' \geq j$. In compactly assembled categories this agrees with \Cref{def:Compact_Morphism}, by \Cref{prop:Compact_Morphism_Characterizations,prop:Compact_Morphisms_Stable}.
	\end{remark}

\begin{remark}
		\label[remark]{rem:Stable_Compact_Morphism_Definitions}
		The vanishing-colimit test in \Cref{prop:Compact_Morphisms_Stable} characterizes weak compactness in any stable category with filtered colimits. Compact assembly is used only to identify this with the natural factorization condition of \Cref{def:Compact_Morphism}, via \Cref{prop:Compact_Morphism_Characterizations}.
	\end{remark}

\begin{corollary}[{cf.\ \cite[Remark~2.38]{Efimov_Large_Categories}}]
		\label[corollary]{cor:Compact_Iff_Identity_Weakly_Compact}
		Let $C$ be a stable category with filtered colimits. Then $x \in C$ is compact if and only if $\id_x$ is weakly compact.
	\end{corollary}

proofs.text:
\begin{proof}
		Suppose that $\id_x$ is weakly compact. By \Cref{prop:Compact_Morphisms_Stable}, we have $\pi_0\Map_{\Ind(C)}(y(x),W) = 0$ for every $W \in \Ind(C)$ with $\colim W \simeq 0$. Applying this to all shifts of $W$, we get $\hom_{\Ind(C)}(y(x),W) \simeq 0$. For $Z = \quotcolim_i z_i$, applying this to the fiber $W$ of the unit $\eta_Z\colon Z \to y(\colim Z)$ shows that
		\begin{align*}
			\colim_i \hom_C(x,z_i) &\simeq \hom_{\Ind(C)}(y(x),Z) \\
			&\to \hom_{\Ind(C)}(y(x),y(\colim Z)) \simeq \hom_C(x,\colim_i z_i)
		\end{align*}
		is an equivalence, i.e.\ $x$ is compact. The converse is \Cref{ex:Weakly_Compact_Basic}(1).
	\end{proof}

claims.statement:
\begin{definition}
		\label[definition]{def:Compactly_Exhaustible}
		Let $C$ be a category with filtered colimits. A \emph{compact exhaustion} of an object $x \in C$ is a sequence $x_0 \to x_1 \to x_2 \to \cdots$ of weakly compact morphisms together with an equivalence $\colim_n x_n \simeq x$. An object is called \emph{compactly exhaustible} if it admits a compact exhaustion.
	\end{definition}

\begin{proposition}[{\cite[Theorem~2.2.15]{Krause_Nikolaus_Putzstuck_Sheaves}}]
		\label[proposition]{prop:Dualizable_Compactly_Exhaustible}
		Let $C \in \PrL_{\st}$. Then $C$ is dualizable if and only if $C$ is generated under colimits by compactly exhaustible objects.
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Compact_Exhaustions_In_Presentable_Categories}
		In \Cref{prop:Dualizable_Compactly_Exhaustible}, stability is used to reduce to ind-objects with vanishing colimit. For general presentable categories, the analogous statement holds provided filtered colimits in $C$ are exact, with ``dualizable'' replaced by ``compactly assembled'' \cite[Theorem~2.2.15]{Krause_Nikolaus_Putzstuck_Sheaves}.
	\end{remark}

\begin{corollary}
		\label[corollary]{cor:Yhat_Universal_Property}
		Let $C$ be compactly assembled and $x \in C$. Then the natural transformation
		\[
			\Map_{\Ind(C)}\big(y(x),\hat{y}(-)\big) \xrightarrow{(\varepsilon)_*} \Map_{\Ind(C)}\big(y(x),y(-)\big) \simeq \Map_C(x,-)
		\]
		exhibits $\Map_{\Ind(C)}(y(x),\hat{y}(-))$ as the terminal object of $\Fun^{\mathrm{filt}}(C,\An)_{/\Map_C(x,-)}$. If $C$ is moreover stable, the same holds for the mapping spectra $\hom_{\Ind(C)}(y(x),\hat{y}(-)) \to \hom_C(x,-)$ in $\Fun^{\mathrm{filt}}(C,\Sp)_{/\hom_C(x,-)}$.
	\end{corollary}

\begin{definition}
		\label[definition]{def:AB6}
		Let $C$ be a category with small products and filtered colimits. We say that $C$ satisfies \emph{(AB6)} if for every set $S$ and every family of functors $F_s\colon J_s \to C$, $s \in S$, with each $J_s$ filtered, the canonical map
		\[
			\colim_{(j_s)_s \in \prod_s J_s} \prod_{s \in S} F_s(j_s) \to \prod_{s \in S} \colim_{j \in J_s} F_s(j)
		\]
		is an equivalence. Note that $\prod_s J_s$ is again filtered.
	\end{definition}

\begin{example}
		\label[example]{ex:AB6_Sets_And_Animae}
		The category of sets and the category $\An$ of animae satisfy (AB6) \cite[Section~2.7]{Efimov_Large_Categories}.
	\end{example}

proofs.text:
\begin{proof}
		We show that the right-hand side has the universal property of the product. Since every object of $\Ind(C)$ is a filtered colimit of representables, it suffices to test against $y(c)$, $c \in C$. As $y(c)$ is compact, and using (AB6) in $\An$, we get natural equivalences
		\begin{align*}
			\Map\Big(y(c),\quotcolim_{(j_s)_s} \prod_s x_{j_s}\Big) &\simeq \colim_{(j_s)_s} \prod_s \Map_C(c,x_{j_s}) \\
			&\simeq \prod_s \colim_{j \in J_s} \Map_C(c,x_j) \\
			&\simeq \prod_s \Map\Big(y(c),\quotcolim_{j \in J_s} x_j\Big). \qedhere
		\end{align*}
	\end{proof}

claims.statement:
\begin{proposition}[{Clausen--Scholze, see \cite[Proposition~2.51]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Dualizable_AB6}
		Let $C \in \PrL_{\st}$. Then $C$ is dualizable if and only if $C$ satisfies (AB6).
	\end{proposition}

proofs.text:
\begin{proof}
		By \Cref{lem:Products_In_Ind}, and since $\colim$ sends $\quotcolim_{(j_s)_s}\prod_s x_{j_s}$ to $\colim_{(j_s)_s}\prod_s x_{j_s}$, the axiom (AB6) for $C$ says exactly that $\colim\colon \Ind(C) \to C$ preserves products of families of ind-objects. Every family of objects of $\Ind(C)$ is of this form. So (AB6) holds if and only if $\colim$ preserves small products, which is equivalent to dualizability of $C$ by \Cref{prop:Dualizable_Further_Characterizations}.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:AB6_And_Small_Ind_Completions}
		In the talk, the implication ``(AB6) $\implies$ dualizable'' was argued directly with $\colim\colon \Ind(C^{\kappa}) \to C$. Note that products in $\Ind(C^{\kappa})$ are not computed by the formula of \Cref{lem:Products_In_Ind}, since a product of $\kappa$-compact objects need not be $\kappa$-compact. This is why the argument passes through the large category $\Ind(C)$, as in the proof of (2) $\implies$ (3) in \Cref{prop:Dualizable_Further_Characterizations}.
	\end{remark}

\begin{remark}
		\label[remark]{rem:AB6_And_Compact_Assembly}
		Since $\Sp$ is compactly generated, hence dualizable, it satisfies (AB6). More generally, by \cite[Remark~2.52]{Efimov_Large_Categories} a presentable, not necessarily stable, category is compactly assembled if and only if it satisfies (AB6) and filtered colimits in it commute with finite limits.
	\end{remark}

\begin{lemma}[{\cite[Proposition~1.8]{Efimov_Large_Categories}}]
		\label[lemma]{lem:Automatic_Strong_Continuity}
		Let $G\colon D \to E$ be a colimit-preserving functor between presentable stable categories, and let $F_i\colon C_i \to D$, $i \in I$, be a family of strongly continuous functors from presentable stable categories $C_i$. Assume that $D$ is generated under colimits by the essential images of the $F_i$, and that each composite $G \circ F_i$ is strongly continuous. Then $G$ is strongly continuous.
	\end{lemma}

proofs.text:
\begin{proof}
		The right adjoints $F_i^R$ are jointly conservative: if $F_i^R(x) \simeq 0$ for all $i$, then the full subcategory of objects $d \in D$ with $\hom_D(d,x) \simeq 0$ is closed under colimits and contains the essential images of the $F_i$, so it is all of $D$, and in particular $x \simeq 0$. Now let $(e_a)_a$ be a diagram in $E$. Since the functors $F_i^R$ and $F_i^RG^R \simeq (GF_i)^R$ preserve colimits, applying $F_i^R$ to the comparison map $\colim_a G^R(e_a) \to G^R(\colim_a e_a)$ gives the comparison map for $(GF_i)^R$, which is an equivalence. Hence the comparison map is an equivalence, i.e.\ $G^R$ preserves colimits.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Proposition~2.53]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Generation_Dualizable}
		Let $D$ be a presentable stable category, and let $F_i\colon C_i \to D$, $i \in I$, be a family of strongly continuous functors from dualizable categories $C_i$. If $D$ is generated under colimits by the essential images of the $F_i$, then $D$ is dualizable.
	\end{proposition}

proofs.text:
\begin{proof}
		As in the proof of \Cref{lem:Automatic_Strong_Continuity}, the right adjoints $F_i^R\colon D \to C_i$ are jointly conservative. They preserve small products, being right adjoints, and filtered colimits, by strong continuity. Let $S$ be a set and let $(x_{s,j})_{j \in J_s}$, $s \in S$, be filtered diagrams in $D$. Applying $F_i^R$ to the comparison map
		\[
			\colim_{(j_s)_s \in \prod_s J_s} \prod_{s \in S} x_{s,j_s} \to \prod_{s \in S} \colim_{j \in J_s} x_{s,j}
		\]
		yields the corresponding comparison map for the diagrams $(F_i^R x_{s,j})_j$ in $C_i$, which is an equivalence by \Cref{prop:Dualizable_AB6}, as $C_i$ is dualizable. Hence the comparison map in $D$ is an equivalence. So $D$ satisfies (AB6), and is dualizable by \Cref{prop:Dualizable_AB6}.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Products_Dualizable}
		In \cite{Efimov_Large_Categories}, the proof of \Cref{prop:Generation_Dualizable} is first reduced to the case of a single functor, using the induced functor $\prod_i C_i \to D$. For this, note that the product $\prod_i C_i$, computed in $\widehat{\Cat}$, is also the coproduct of the $C_i$ in $\PrL_{\st}$, as colimits in $\PrL$ are computed as limits along the right adjoints (\Cref{sec:PrL_Tensor_Products}). If each $C_i$ is dualizable, then so is $\prod_i C_i$: products and filtered colimits in $\prod_i C_i$ are computed componentwise, so (AB6) holds in $\prod_i C_i$ since it holds in each $C_i$. Alternatively, if $C_i$ is a retract of a compactly generated category $\widetilde{C}_i$ in $\PrL_{\st}$, then $\prod_i C_i$ is a retract of $\prod_i\widetilde{C}_i$, which is compactly generated by the objects with a single nonzero component, which is compact.
	\end{remark}

\begin{definition}[{\cite[Definition~2.54]{Efimov_Large_Categories}}]
		\label[definition]{def:Image_Functor}
		Let $F\colon C \to D$ be a colimit-preserving functor between presentable stable categories. The \emph{image} $\Im(F) \subseteq D$ is the smallest full stable subcategory of $D$ which contains the essential image of $F$ and is closed under colimits, i.e.\ the localizing subcategory generated by the essential image of $F$.
	\end{definition}

\begin{corollary}[{\cite[Corollary~2.55]{Efimov_Large_Categories}}]
		\label[corollary]{cor:Image_Dualizable}
		Let $F\colon C \to D$ be a strongly continuous functor between presentable stable categories, and assume that $C$ is dualizable. Then $\Im(F)$ is dualizable, and the inclusion $j\colon \Im(F) \hookrightarrow D$ is strongly continuous.
	\end{corollary}

proofs.text:
\begin{proof}
		Write $F = j \circ F'$ with $F'\colon C \to \Im(F)$. Since $j$ is fully faithful, the right adjoint of $F'$ is $F^R \circ j$, which preserves colimits. So $F'$ is strongly continuous, and its essential image generates $\Im(F)$ under colimits. Hence $\Im(F)$ is dualizable by \Cref{prop:Generation_Dualizable}. Since $j \circ F' = F$ is strongly continuous, \Cref{lem:Automatic_Strong_Continuity} shows that $j$ is strongly continuous.
	\end{proof}

\begin{proof}
		The functor $B \otimes_A -$ is a localization by assumption, and it is strongly continuous since its right adjoint $\res$ preserves colimits. Hence $\D(A \to B) \hookrightarrow \D(A) \to \D(B)$ is a strongly continuous localization sequence (\Cref{lem:Strong_Continuity_Localization_Sequence}), and $\D(A \to B)$ is dualizable by \Cref{prop:Localization_Sequence_Dualizable}. The final statement follows from the definition of $K^{\cont}$, see \Cref{sec:Continuous_K_Theory_Intro}.
	\end{proof}

claims.statement:
\begin{proposition}
		\label[proposition]{prop:Every_Dualizable_Kernel}
		Every dualizable category is of the form $\D(E \to E')$ for some homological epimorphism $E \to E'$ of $\bbE_1$-rings.
	\end{proposition}

\begin{theorem}[{\cite[Section~2.10, especially Corollary~2.10.6]{Krause_Nikolaus_Putzstuck_Sheaves}}]
		\label[theorem]{thm:H_Unital}
		For a non-unital ring spectrum $I$, the following are equivalent:
		\begin{enumerate}
			\item $I$ is h-unital;
			\item the map $\S \oplus I \to \S$ is a homological epimorphism;
			\item for every fiber sequence $I \to A \to B$ in which $A \to B$ is a map of unital ring spectra, the map $A \to B$ is a homological epimorphism.
		\end{enumerate}
	\end{theorem}

\begin{example}
		\label[example]{ex:Homological_Epis}
		The following maps are homological epimorphisms, and hence give rise to dualizable categories $\D(A \to B)$:
		\begin{enumerate}
			\item A localization $A \to A[S^{-1}]$ of a commutative ring at a multiplicative subset. More generally, if $A$ is a commutative Noetherian ring, the kernel of every homological epimorphism out of $A$ is compactly generated: the associated localization of $\D(A)$ is smashing, so this follows from \cite[Theorem~3.3 and Corollary~3.4]{Neeman_Chromatic_Tower}.
			\item A surjection $A \twoheadrightarrow B$ of perfect $\F_p$-algebras: the higher $\mathrm{Tor}^A$-groups between perfect $A$-algebras vanish by \cite[Lemma~3.16]{Bhatt_Scholze_Witt_Grassmannian}, so $B \otimes^{\bL}_A B \simeq B$. Similarly, if $A$ is an integral perfectoid ring and $B$ is a perfect $\F_p$-algebra, any surjection $A \twoheadrightarrow B$ is a homological epimorphism. Indeed, the derived $p$-completed tensor product of perfectoid rings is discrete by the proof of \cite[Lemma~10.3]{Bhatt_Scholze_Prisms}. Here $B \otimes^{\bL}_A B$ is already derived $p$-complete, since it is a $B$-module, and its degree-zero homology is $B$.
			\item (Wodzicki) If $A$ is a unital C$^*$-algebra and $I \subseteq A$ a closed two-sided $*$-ideal, then $A \to A/I$ is a homological epimorphism. For $A = B(\Hh)$ and $I = \Kk(\Hh)$, this gives the category $\D(\Kk)$ from \Cref{ex:Compact_Operators_Intro}.
			\item (Almost ring theory) If $A$ is a ring and $I \subseteq A$ is a two-sided ideal with $I^2 = I$ which is flat as a left or right $A$-module, then $A \to A/I$ is a homological epimorphism. We discuss this in detail in \Cref{sec:Almost_Ring_Theory}.
		\end{enumerate}
	\end{example}

\begin{definition}
		\label[definition]{def:Almost_Modules}
		The category of \emph{$(A,I)$-almost modules} is the Serre quotient
		\[
			(A,I)^a\text{-}\Mod := A\text{-}\Mod/(A/I)\text{-}\Mod.
		\]
	\end{definition}

\begin{example}
		\label[example]{ex:Almost_Modules}
		\leavevmode
		\begin{enumerate}
			\item If $I = A$, then $(A/I)\text{-}\Mod = 0$ and $(A,A)^a\text{-}\Mod = A\text{-}\Mod$.
			\item The motivating examples come from non-discrete valuation rings: let $A$ be a valuation ring of rank one whose value group is not discrete, e.g.\ $A = \Oo_{\C_p}$, and let $I = \mm$ be its maximal ideal. Then $\mm^2 = \mm$, since every element of $\mm$ is a product of two elements of $\mm$, and $\mm$ is flat since it is torsion-free over a valuation ring. An $A$-module is called \emph{almost zero} if it is killed by $\mm$; for instance, the residue field $A/\mm$ becomes zero in the almost category. This is the setting of Faltings' almost purity theorem in $p$-adic Hodge theory.
		\end{enumerate}
	\end{example}

\begin{lemma}
		\label[lemma]{lem:Almost_Restriction_FF}
		The functor $\res\colon \D(A/I) \to \D(A)$ is fully faithful. In particular, $L$ is a localization and $A \to A/I$ is a homological epimorphism.
	\end{lemma}

proofs.text:
\begin{proof}
		As explained at the beginning of \Cref{sec:Homological_Epimorphisms}, it suffices to show that the multiplication map $A/I \otimes^{\bL}_A A/I \to A/I$ is an equivalence. Using the short exact sequence $0 \to I \to A \to A/I \to 0$ of right $A$-modules, we find
		\begin{align*}
			\mathrm{Tor}^A_0(A/I,A/I) &= A/I, \\
			\mathrm{Tor}^A_1(A/I,A/I) &\cong I/I^2 = 0, \\
			\mathrm{Tor}^A_k(A/I,A/I) &\cong \mathrm{Tor}^A_{k-1}(I,A/I) = 0 \quad \text{for } k \geq 2,
		\end{align*}
		where the last vanishing uses flatness of $I$ as a right $A$-module.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Almost_Essential_Image}
		The essential image of $\res\colon \D(A/I) \hookrightarrow \D(A)$ is the full subcategory
		\[
			\D_{(A/I)\text{-}\Mod}(A) := \{X \in \D(A) \mid IH_n(X) = 0 \text{ for all } n \in \Z\}
		\]
		of complexes whose homology lies in the Serre subcategory $(A/I)\text{-}\Mod$. Moreover, the kernel of $L$ consists of those $X \in \D(A)$ with $X \simeq I \otimes^{\bL}_A X$, and $I \otimes^{\bL}_A X \in \ker(L)$ for every $X \in \D(A)$.
	\end{lemma}

\begin{proposition}
		\label[proposition]{prop:Almost_Derived_Category}
		There is an equivalence
		\[
			\D((A,I)^a\text{-}\Mod) \simeq \ker\big(L\colon \D(A) \to \D(A/I)\big),
		\]
		and $\ker(L) = \D(A \to A/I)$ is dualizable. More precisely, $\D((A,I)^a\text{-}\Mod) \hookrightarrow \D(A) \xrightarrow{L} \D(A/I)$ is a strongly continuous localization sequence, and $\D((A,I)^a\text{-}\Mod)$ is also the kernel of $L$ computed in $\Pr^{\dual}$.
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Almost_General}
		In the talk, the last part of \Cref{prop:Almost_Derived_Category} was deduced from the general fact that the inclusion $\Pr^{\dual} \hookrightarrow \PrL_{\st}$ preserves pullbacks along localizations (\Cref{prop:Dualizable_Pullbacks}(2)). Efimov \cite[Example~2.26]{Efimov_Large_Categories} shows that $\D((A,I)^a\text{-}\Mod)$ is dualizable even without any flatness assumption on $I$: in general, $\D(A) \to \D_{(A/I)\text{-}\Mod}(A)$ is still a strongly continuous localization, identified with $B \otimes_A -$ for a connective DG ring $B$ with $H_0(B) = A/I$, and $B = A/I$ if $I$ is flat as a right or left $A$-module.
	\end{remark}

\begin{proposition}
		\label[proposition]{prop:Almost_No_Compacts}
		If $I \subseteq \mathrm{Jac}(A)$ is contained in the Jacobson radical of $A$, then $\D((A,I)^a\text{-}\Mod)$ has no nonzero compact objects.
	\end{proposition}

\begin{example}
		\label[example]{ex:Almost_Modules_Over_Cp}
		In the situation of \Cref{ex:Almost_Modules}(2), $A = \Oo_{\C_p}$ is local with maximal ideal $\mm = \mathrm{Jac}(A)$. Hence $\D((\Oo_{\C_p},\mm)^a\text{-}\Mod)$ is a dualizable category without nonzero compact objects.
	\end{example}

\begin{lemma}
		\label[lemma]{lem:Ind_Of_Poset}
		The category $\Ind(P)$ is (equivalent to) a partially ordered set. Explicitly, every object of $\Ind(P)$ is of the form $\quotcolim_{s \in S} s$ for a directed subset $S \subseteq P$, and for directed subsets $S,T \subseteq P$ we have
		\begin{align*}
			\Map_{\Ind(P)}\Big(\quotcolim_{s \in S} s, \quotcolim_{t \in T} t\Big) &= \lim_{s \in S\catop}\colim_{t \in T}\Map_P(s,t) \\
			&\simeq \begin{cases} * & \text{if for all } s \in S \text{ there is } t \in T \text{ with } s \leq t, \\ \emptyset & \text{otherwise.}\end{cases}
		\end{align*}
		Hence $\Ind(P)$ is equivalent to the poset of \emph{ideals} of $P$, i.e.\ non-empty, directed, downward closed subsets $J \subseteq P$, ordered by inclusion, via $S \mapsto {\downarrow}S := \{p \in P \mid p \leq s \text{ for some } s \in S\}$.
	\end{lemma}

proofs.text:
\begin{proof}
		By \Cref{thm:Filtered_Posets_Cofinal}, every object of $\Ind(P)$ is a colimit of representables indexed by a filtered poset $I$, i.e.\ of the form $\quotcolim_{i \in I} p_i$ for a functor $p\colon I \to P$. The image $S = p(I)$ is a directed subset, and the map $I \to S$ is cofinal by \Cref{lem:Cofinality_Posets} (for $s \in S$, the set $\{i \mid s \leq p_i\}$ is non-empty and upward closed in the filtered poset $I$, hence filtered). This proves the first claim. The formula for mapping spaces follows from \Cref{constr:Ind_Large}: each $\Map_P(s,t)$ is either empty or contractible, filtered colimits of such spaces are again empty or contractible (and contractible if and only if one of the terms is), and a limit of such spaces is contractible if and only if all terms are. In particular, all mapping spaces in $\Ind(P)$ are empty or contractible, so $\Ind(P)$ is a poset. Finally, the condition in the formula only depends on ${\downarrow}S$ and ${\downarrow}T$: it says precisely that ${\downarrow}S \subseteq {\downarrow}T$.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Posets_Accessible}
		Let $P$ be a small partially ordered set admitting directed suprema. Then $P$ is accessible.
	\end{lemma}

proofs.text:
\begin{proof}
		Let $\kappa$ be a regular cardinal with $\kappa > |P|$. Let $D \subseteq P$ be a $\kappa$-directed subset. Since $|D| < \kappa$, the set $D$ itself has an upper bound in $D$ (\Cref{lem:Kappa_Filtered_Posets}), i.e.\ $D$ has a largest element. It follows that every $\kappa$-filtered diagram in $P$ has a cofinal constant subdiagram, so that $\kappa$-filtered colimits in $P$ are ``trivial'': every object of $P$ is $\kappa$-compact, and the Yoneda embedding $P \to \Ind_{\kappa}(P)$ is an equivalence, as every $\kappa$-filtered colimit of representable presheaves on $P$ is representable. Hence $P \simeq \Ind_{\kappa}(P^{\kappa})$ is $\kappa$-accessible.
	\end{proof}

claims.statement:
\begin{definition}
		\label[definition]{def:Continuous_Poset}
		A partially ordered set $P$ is called \emph{continuous} if it admits directed suprema and the functor $\colim = \sup\colon \Ind(P) \to P$ admits a left adjoint $\hat{y}\colon P \to \Ind(P)$.
	\end{definition}

\begin{definition}
		\label[definition]{def:Way_Below}
		Let $P$ be a poset admitting directed suprema, and let $a,b \in P$. We say that $a$ is \emph{way below} $b$, written $a \ll b$, if for every directed subset $T \subseteq P$ with $b \leq \sup T$ there exists $t \in T$ with $a \leq t$. We write
		\[
			P_{\ll b} := \{a \in P \mid a \ll b\}.
		\]
	\end{definition}

\begin{remark}
		\label[remark]{rem:Way_Below_Basics}
		\leavevmode
		\begin{enumerate}
			\item If $a \ll b$, then $a \leq b$: apply the definition to $T = \{b\}$.
			\item If $a' \leq a \ll b \leq b'$, then $a' \ll b'$.
			\item An element $b$ is compact in $P$ (i.e.\ $\Map_P(b,-)$ preserves filtered colimits) if and only if $b \ll b$.
			\item If $P$ is continuous, then $\hat{y}(b) \subseteq P_{\ll b}$ for every $b$. Indeed, let $s \in \hat{y}(b)$ and let $T$ be directed with $b \leq \sup T$. By \eqref{eq:Yhat_Poset}, there exists $t \in T$ with $s \leq t$, so $s \ll b$.
		\end{enumerate}
	\end{remark}

\begin{proposition}
		\label[proposition]{prop:Continuous_Poset_Characterization}
		Let $P$ be a poset admitting directed suprema. Then $P$ is continuous if and only if for every $b \in P$ the subset $P_{\ll b}$ is directed and $\sup P_{\ll b} = b$. In this case, $\hat{y}(b) = P_{\ll b}$, viewed as an object of $\Ind(P)$.
	\end{proposition}

\begin{example}
		\label[example]{ex:Continuous_Poset_Reals}
		The poset $P = \R \cup \{\infty\}$ (with its usual order) admits directed suprema: the supremum of a non-empty subset is its usual supremum if the subset is bounded, and $\infty$ otherwise. We claim that $a \ll b$ if and only if $a < b$. If $a < b$ and $T$ is directed with $b \leq \sup T$, then $\sup T > a$, so some $t \in T$ satisfies $t > a$. Conversely, suppose $a \ll b$; then $a \leq b$ by \Cref{rem:Way_Below_Basics}(1). If $a = b$, consider the directed set $T = \{b - 1/n \mid n \geq 1\}$ (for $b \in \R$) resp.\ $T = \N$ (for $b = \infty$): it has supremum $b$, but no element $t \in T$ satisfies $b \leq t$. Hence $a < b$. It follows that $P_{\ll b} = \{a \mid a < b\}$ is directed with supremum $b$, so $P$ is continuous by \Cref{prop:Continuous_Poset_Characterization}, with $\hat{y}(b) = \quotcolim_{a < b} a$. Note that $P$ has no compact elements.
	\end{example}

\begin{example}
		\label[example]{ex:Continuous_Poset_Opens}
		Let $X$ be a locally compact Hausdorff space and let $\Open(X)$ be the poset of open subsets of $X$, ordered by inclusion. Directed suprema in $\Open(X)$ are unions. We claim that
		\[
			U \ll V \iff \overline{U} \text{ is compact and } \overline{U} \subseteq V,
		\]
		in which case we write $U \Subset V$. Suppose first that $\overline{U}$ is compact and $\overline{U} \subseteq V$, and let $(W_i)_{i \in I}$ be a directed family of open subsets with $V \subseteq \bigcup_i W_i$. Then the $W_i$ cover the compact set $\overline{U}$, so finitely many of them do, and since the family is directed, a single $W_i$ contains $\overline{U} \supseteq U$. Conversely, let $U \ll V$. Since $X$ is locally compact Hausdorff, every point $x \in V$ has an open neighbourhood $W$ with $\overline{W}$ compact and $\overline{W} \subseteq V$. Hence $V$ is the union of the family $\{W \in \Open(X) \mid W \Subset V\}$, which is directed since $W_1 \cup W_2 \Subset V$ if $W_1,W_2 \Subset V$. By assumption, $U \subseteq W$ for some $W \Subset V$, and then $\overline{U} \subseteq \overline{W}$ is a closed subset of a compact set, hence compact, and $\overline{U} \subseteq \overline{W} \subseteq V$.

		The argument shows moreover that $\Open(X)_{\ll V}$ is directed with union $V$, so $\Open(X)$ is a continuous poset by \Cref{prop:Continuous_Poset_Characterization}, with $\hat{y}(V) = \quotcolim_{U \Subset V} U$. Its compact elements are the open subsets $U$ with $U \Subset U$, i.e.\ the compact open subsets of $X$.
	\end{example}

\begin{remark}
		\label[remark]{rem:Continuous_Posets_Sheaves}
		If $X$ is a locally compact Hausdorff space, then the morphism $h_U \to h_V$ of representable sheaves on $X$ is a compact morphism in $\Shv(X;\Sp)$ whenever $U \Subset V$ (Mathew, Lecture 3). Since every open $V$ is the union of a sequence $U_0 \Subset U_1 \Subset \cdots$ if $X$ is second countable, this suggests (and, suitably generalized, proves) that $\Shv(X;\Sp)$ is generated by sequential colimits along compact morphisms and hence dualizable, cf.\ \Cref{rem:Omega_1_Compact_Compact_Morphisms}. We will return to this in \Cref{chap:Sheaves}.
	\end{remark}

\begin{proposition}[{\cite[Proposition~2.76]{Efimov_Large_Categories}}]
		\label[proposition]{prop:SOD_Dualizable}
		Let $E = \lra{C,D}$ be a semiorthogonal decomposition of presentable stable categories in the sense of \Cref{def:Semiorthogonal_Decomposition}. Then $E$ is dualizable if and only if $C$ and $D$ are dualizable. In this case $E^{\omega} = \lra{C^{\omega},D^{\omega}}$.
	\end{proposition}

proofs.text:
\begin{proof}
		The projections $i_C^L$ and $i_D^R$ preserve colimits, so $C$ and $D$ are retracts of $E$ in $\PrL_{\st}$. Thus dualizability of $E$ implies that of $C$ and $D$.

		Conversely, if $C$ and $D$ are dualizable, then $E$ is dualizable by \Cref{prop:Generation_Dualizable}, since the strongly continuous inclusions $i_C$ and $i_D$ jointly generate $E$.

		The inclusions preserve compact objects. The projection $i_C^L$ does too, since its right adjoint $i_C$ preserves colimits. For compact $e \in E$, the cofiber sequence $i_Di_D^Re \to e \to i_Ci_C^Le$ therefore shows that $i_Di_D^Re$ is compact. Since $i_D$ is fully faithful and preserves filtered colimits, $i_D^Re$ is compact in $D$. This restricts the semiorthogonal decomposition to compact objects.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Proposition~2.77]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Gluing_Dualizable}
		Let $F\colon D \to C$ be an accessible exact functor between dualizable categories, and let $E=C\oplus_F D$ be the gluing of \Cref{constr:Semiorthogonal_Gluing}. Then the following are equivalent:
		\begin{enumerate}
			\item $F$ preserves colimits;
			\item $E$ is dualizable, and $i_C$ and $i_D$ are strongly continuous.
		\end{enumerate}
		In this case, $i_C$ and $i_D$ exhibit a semiorthogonal decomposition $E = \lra{C,D}$.
	\end{proposition}

proofs.text:
\begin{proof}
		(2) $\implies$ (1): If $i_C$ is strongly continuous, then $i_C^R$ preserves colimits, and hence so does $i_C^Ri_D \simeq \Omega F$. So $F$ preserves colimits. This does not use the dualizability of $E$.

		(1) $\implies$ (2): If $F$ preserves colimits, then $i_C^R(x,y,u) = \fib(u\colon x \to F(y))$ preserves colimits, so $i_C$ is strongly continuous. The functor $i_D$ is always strongly continuous. The functors $i_C$ and $i_D$ are fully faithful, we have $\hom_E(i_D(d),i_C(c)) \simeq 0$, and every object of $E$ is an extension of an object of $i_C(C)$ by one of $i_D(D)$. So we obtain a semiorthogonal decomposition $E = \lra{C,D}$ in the sense of \Cref{def:Semiorthogonal_Decomposition}, and $E$ is dualizable by \Cref{prop:SOD_Dualizable}.
	\end{proof}

claims.statement:
\begin{warning}
		\label[warning]{warn:Extensions_Not_Dualizable}
		The converse of \Cref{prop:Localization_Sequence_Dualizable} fails: if $K$ and $E$ are dualizable, then $D$ need not be dualizable, even if $K$ and $E$ are compactly generated. An explicit counterexample is given in \Cref{ex:Extension_Not_Dualizable} below. However, dualizable categories are closed under pullbacks along strongly continuous localizations, see \Cref{prop:Dualizable_Pullbacks}(2).
	\end{warning}

\begin{proposition}[{Efimov \cite[Proposition~6.3]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Extension_Dualizable_Tate}
		For the extension $\Ind(A)\xrightarrow{i} E\xrightarrow{q}\Ind(B)$ above, the following are equivalent:
		\begin{enumerate}
			\item $E$ is dualizable;
			\item $E$ is compactly generated;
			\item $T_b$ belongs to $\mathrm{Tate}(A)$ for every $b\in B$.
		\end{enumerate}
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Tate_Classification_Of_Extensions}
		Passing to compact objects in a compactly generated extension $E$ gives $A\to E^\omega\to B$. More generally, short exact sequences $A \to E_0 \to B$ in $\Cat_{\perf}$ correspond to exact functors $B \to \mathrm{Tate}(A)$; this classification first appeared in \cite[Theorem~A.5.1 and Corollary~A.5.10]{Hermitian_II}, see also \cite[Theorem~6.4]{Efimov_Large_Categories}.
	\end{remark}

\begin{definition}[{\cite[Chapter~1, Definition~9.1.2]{GaitsgoryRozenbluym2017StudyDAG}}]
		\label[definition]{def:Rigid_Category_Detailed}
		Let $C \in \CAlg(\PrL_{\st})$ be a presentably symmetric monoidal stable category, with unit $\unit_C$ and multiplication $\mu\colon C \otimes C \to C$. Then $C$ is called \emph{rigid} if
		\begin{enumerate}
			\item the unit $\unit_C$ is compact in $C$, or equivalently, the unit functor $u\colon \Sp \to C$, $\S \mapsto \unit_C$, is strongly continuous;
			\item the right adjoint $\mu^R\colon C \to C \otimes C$ preserves colimits, and its canonical lax $C \otimes C$-linear structure is strict; equivalently, $\mu$ admits a right adjoint in $\Mod_{C \otimes C}(\PrL_{\st})$.
		\end{enumerate}
	\end{definition}

\begin{remark}
		\label[remark]{rem:Equivalent_Rigidity_Definitions}
		The equivalence of the two formulations in (2) is a general fact about adjunctions internal to module categories: a right adjoint of a $C \otimes C$-linear functor inherits a lax $C \otimes C$-linear structure, and it is a right adjoint in $\Mod_{C \otimes C}(\PrL_{\st})$ if and only if it preserves colimits and this lax structure is strict. \Cref{def:Rigid_Category_Detailed} is the definition of Gaitsgory--Rozenblyum, and it agrees with Ramzi's definition \cite[Definitions~4.5 and~4.36]{Ramzi_Locally_Rigid} (Ramzi additionally requires $C$ to be dualizable, which is automatic by \Cref{prop:Rigid_Self_Dual_Detailed}). It is also equivalent to \Cref{def:Rigid_Category}, which asks that for every finite set $I$ the multiplication $\mu_I\colon C^{\otimes I} \to C$ admits a right adjoint in $\Mod_{C^{\otimes I}}(\PrL_{\st})$. Indeed, for $I = \emptyset$ the map $\mu_{\emptyset}$ is the unit functor $u\colon \Sp \to C$, and $\Mod_{\Sp}(\PrL_{\st}) = \PrL_{\st}$, so this case is condition (1); the case $|I| = 1$ is vacuous, and the case $|I| = 2$ is condition (2). Conversely, if (2) holds, then by induction $\mu_{I \sqcup \{*\}} = \mu \circ (\mu_I \otimes \id_C)$ is a composite of two functors admitting right adjoints in $\Mod_{C^{\otimes I} \otimes C}(\PrL_{\st})$: for $\mu_I \otimes \id_C$ this follows by tensoring the adjunction for $\mu_I$ with $C$, and for $\mu$ by restricting the $C \otimes C$-linear adjunction along the algebra map $\mu_I \otimes \id_C\colon C^{\otimes I} \otimes C \to C \otimes C$.
	\end{remark}

\begin{definition}
		\label[definition]{def:Trace_Class}
		Let $C$ be a symmetric monoidal category. A morphism $f\colon x \to y$ in $C$ is called \emph{trace-class} if there exist an object $z \in C$ and maps $\alpha\colon \unit_C \to y \otimes z$ and $\beta\colon z \otimes x \to \unit_C$ such that $f$ is homotopic to the composite
		\[
			x \simeq \unit_C \otimes x \xrightarrow{\alpha \otimes x} y \otimes z \otimes x \xrightarrow{y \otimes \beta} y \otimes \unit_C \simeq y.
		\]
	\end{definition}

\begin{lemma}
		\label[lemma]{lem:Identity_Trace_Class}
		Let $C$ be a symmetric monoidal category whose homotopy category is idempotent complete; for instance, $C$ stable and idempotent complete \cite[Lemma~1.2.4.6]{lurie2016HA}. Then an object $x \in C$ is dualizable if and only if $\id_x$ is trace-class.
	\end{lemma}

\begin{remark}
		\label[remark]{rem:Trace_Class_Basics}
		\leavevmode
		\begin{enumerate}
			\item If $C$ is closed, write $x^{\vee} := \iHom(x,\unit_C)$ for the \emph{predual} of $x$. Then $f$ is trace-class if and only if the map $\unit_C \to \iHom(x,y)$ classifying $f$ factors through the canonical map $y \otimes x^{\vee} \to \iHom(x,y)$: given $(z,\alpha,\beta)$ as above, $\beta$ is adjoint to a map $z \to x^{\vee}$, and composing $\alpha$ with it gives the desired factorization; conversely, given a factorization $\unit_C \to y \otimes x^{\vee}$, take $z = x^{\vee}$ and $\beta$ the evaluation map.
			\item Trace-class morphisms form a two-sided ideal: if $f$ is trace-class with witness $(z,\alpha,\beta)$, then $hfk$ is trace-class with witness $(z,(h \otimes z)\alpha,\beta(z \otimes k))$.
			\item If $C$ is stable and idempotent complete (for instance presentable and stable), then the identity of $x$ is trace-class if and only if $x$ is dualizable, see \Cref{lem:Identity_Trace_Class}.
			\item A symmetric monoidal functor preserves trace-class morphisms, since it preserves the data $(z,\alpha,\beta)$.
		\end{enumerate}
	\end{remark}

\begin{lemma}
		\label[lemma]{lem:Trace_Class_Compact}
		Let $C \in \CAlg(\PrL_{\st})$ be such that $\unit_C$ is compact. Then every trace-class morphism in $C$ is compact in the sense of \Cref{def:Compact_Morphism}.
	\end{lemma}

\begin{theorem}[{Ramzi \cite[Corollaries~2.6, 4.55 and~4.60, Example~2.9]{Ramzi_Locally_Rigid}; see also \cite[Propositions~1.6 and~1.7]{Efimov_Inverse_Limits}}]
		\label[theorem]{thm:Rigid_Trace_Class}
		Let $C \in \CAlg(\PrL_{\st})$. Then the following are equivalent:
		\begin{enumerate}
			\item $C$ is rigid;
			\item $\unit_C$ is compact, and $C$ is generated under colimits by objects of the form $\colim(x_0 \to x_1 \to x_2 \to \cdots)$ in which each map $x_n \to x_{n+1}$ is trace-class;
			\item $C$ is dualizable, and a morphism in $C$ is compact if and only if it is trace-class.
		\end{enumerate}
	\end{theorem}

\begin{corollary}
		\label[corollary]{cor:Rigid_Functors_Strongly_Continuous}
		Let $F\colon C \to D$ be a colimit-preserving symmetric monoidal functor between rigid categories. Then $F$ is strongly continuous. Consequently, the category $\mathrm{Rig}$ of rigid symmetric monoidal categories and colimit-preserving symmetric monoidal functors is a full subcategory of $\CAlg(\Pr^{\dual})$.
	\end{corollary}

proofs.text:
\begin{proof}
		By \Cref{thm:Rigid_Trace_Class}, the compact morphisms in $C$ are trace-class. Since $F$ is symmetric monoidal, it preserves trace-class morphisms (\Cref{rem:Trace_Class_Basics}(4)), and trace-class morphisms in $D$ are compact by \Cref{lem:Trace_Class_Compact}. So $F$ preserves compact morphisms, and hence is strongly continuous by \Cref{prop:Strongly_Continuous_Compact_Morphisms}.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Strong_Continuity_From_Rigid_Source}
		The argument shows more generally that a colimit-preserving symmetric monoidal functor $F\colon C \to D$ with $C$ rigid and $D$ dualizable with compact unit is strongly continuous. In fact, the dualizability hypothesis on $D$ can be removed \cite[Proposition~1.9]{Efimov_Inverse_Limits}.
	\end{remark}

\begin{example}
		\label[example]{ex:Rigid_Compactly_Generated}
		Let $C \in \CAlg(\PrL_{\st})$ be compactly generated. Then $C$ is rigid if and only if $\unit_C$ is compact and every compact object of $C$ is dualizable, if and only if the compact objects of $C$ are precisely the dualizable objects \cite[Chapter~1, Lemma~9.1.5 and Corollary~9.1.7]{GaitsgoryRozenbluym2017StudyDAG}. Indeed, if $\unit_C$ is compact, then dualizable objects are compact (as $\Map(x,-) \simeq \Map(\unit_C,x^{\vee} \otimes -)$), and conversely if all compact objects are dualizable, then $C = \Ind(C^{\omega})$ is generated by objects whose identity is trace-class, so (2) of \Cref{thm:Rigid_Trace_Class} holds. Examples include $\D(R)$ for a commutative ring $R$, more generally $\D_{\mathrm{qc}}(X)$ for a qcqs scheme $X$, and $\Sp$ itself.
	\end{example}

\begin{example}
		\label[example]{ex:Shv_Compact_Hausdorff_Rigid}
		Let $X$ be a compact Hausdorff space. Then $\Shv(X;\Sp)$ is rigid; this can be seen as a manifestation of Verdier duality, see \cite[Example~1.4]{Efimov_Inverse_Limits}. For instance, the unit (the constant sheaf) is compact since global sections $\Gamma(X;-)$ commute with filtered colimits for compact $X$ \cite[Corollary~7.3.4.12]{lurie2009HTT}. In particular, $\Shv(X;\Sp)$ is dualizable and self-dual. For every presentable stable category $D$ we have $\Shv(X;D) \simeq \Shv(X;\Sp) \otimes D$ \cite[Proposition~2.8.7]{Krause_Nikolaus_Putzstuck_Sheaves}, so $\Shv(X;D)$ is dualizable whenever $D$ is. We will study these categories in detail in \Cref{chap:Sheaves}.
	\end{example}

\begin{example}
		\label[example]{ex:Locally_Rigid_Sheaf_Categories}
		If $X$ is merely locally compact Hausdorff and not compact, then $\Shv(X;\Sp)$ is not rigid, since the unit is not compact. It is still dualizable, and even \emph{locally rigid} in the sense of Ramzi \cite[Definition~4.5 and Example~4.10]{Ramzi_Locally_Rigid} (see also \cite[Definition~1.36 and Example~1.38]{Efimov_Inverse_Limits} and \cite[Example~4.2.9, Corollary~4.4.13]{Krause_Nikolaus_Putzstuck_Sheaves}): it satisfies condition (2) of \Cref{def:Rigid_Category_Detailed}. Indeed, for $j\colon X \hookrightarrow X^+$ the one-point compactification, $j_!$ identifies $\Shv(X;\Sp)$ with a smashing ideal in the rigid category $\Shv(X^+;\Sp)$.
	\end{example}

\begin{remark}
		\label[remark]{rem:Rigidification_Via_Idempotent_Ideals}
		Clausen gives the same construction in his third lecture \citep{Clausen_Efimov_K_Theory_Lecture_3} as a special case of a construction for a presentable stable category $C$ and a two-sided ideal $S$ of maps. He assumes that $S$ contains the zero maps, is closed under finite sums and shifts in both directions, and satisfies the following cofiber condition. Given composable maps of arrows $u\to v\to w$ in $C$, if both maps on sources and both maps on targets lie in $S$, then $\cofib(u)\to\cofib(w)$ lies in $S$.

		Clausen forms $(C,S)^{\dual}$ by taking formal rational telescopes with transitions in $S$ and closing under colimits. For a dualizable category $D$, strongly continuous functors $D\to(C,S)^{\dual}$ correspond to colimit-preserving functors $D\to C$ that take compact maps into $S$. For symmetric monoidal $C$ he takes $S$ to be the trace-class maps to obtain $C^{\rig}$. Rational indexing matters here. If every map in $S$ factors as two maps in $S$, then \Cref{lem:Interpolation} lets us refine any sequence of maps in $S$ to a rational diagram with the same colimit. Only this last simplification uses the factorization hypothesis.
	\end{remark}

\begin{definition}[{\cite[Definition~1.25]{Efimov_Inverse_Limits}; cf.\ \cite[Definition~8.5]{Clausen_Scholze_Complex_Geometry} and \cite[Definitions~13.10 and~13.12]{Scholze_Analytic_Geometry}}]
		\label[definition]{def:Nuclear}
		An object $M \in C$ is called \emph{nuclear} if every morphism $P \to M$ from a compact object $P \in C^{\omega}$ is trace-class. We denote by $\Nuc(C) \subseteq C$ the full subcategory of nuclear objects. An object $M$ is called \emph{basic nuclear} if $M \simeq \colim(P_0 \to P_1 \to P_2 \to \cdots)$ with each $P_n$ compact and each map $P_n \to P_{n+1}$ trace-class.
	\end{definition}

\begin{lemma}
		\label[lemma]{lem:Trace_Class_Interleaving}
		Let $f\colon x\to y$ be trace-class and let $P\in C$. The naturality square for the tensor-to-internal-Hom comparison admits a diagonal making both triangles commute up to homotopy:
		\[
			\begin{tikzcd}[column sep=large]
				x\otimes P^{\vee} \rar["f\otimes P^{\vee}"] \dar & y\otimes P^{\vee} \dar \\
				\iHom(P,x) \rar["{\iHom(P,f)}"'] \arrow[ur,dashed] & \iHom(P,y)
			\end{tikzcd}
		\]
	\end{lemma}

proofs.text:
\begin{proof}
		Choose a tensor $t\colon\unit_C\to y\otimes x^\vee$ representing $f$ as in \Cref{rem:Trace_Class_Basics}(1). For the diagonal, tensor with $t$ and then compose a functional on $x$ with a map from $P$ to $x$:
		\[
			\iHom(P,x)\xrightarrow{t\otimes\id}
			y\otimes x^\vee\otimes\iHom(P,x)\longrightarrow y\otimes P^\vee.
		\]
		The last arrow uses internal composition $x^\vee\otimes\iHom(P,x)\to P^\vee$, since $x^\vee=\iHom(x,\unit_C)$.

		For the lower triangle, evaluate on $P$. By associativity of composition, composing a functional with a map from $P$ and then evaluating on $P$ is the same as first evaluating the map into $x$ and then applying the functional. Contracting $t$ against this $x$ gives $f$, so the composite is postcomposition with $f$.

		For the upper triangle, start with $x\otimes P^\vee$. The composite $x^\vee\otimes x\otimes P^\vee\to x^\vee\otimes\iHom(P,x)\to P^\vee$ uses the evaluation $x^\vee\otimes x\to\unit_C$ and leaves the factor $P^\vee$ untouched. The composite around this triangle is therefore the contraction of $t$ against $x$, tensored with $\id_{P^\vee}$. This is $f\otimes P^\vee$.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Nuclear_Colimit_Interleaving}
		Let $M \simeq \colim_{i \in I} M_i$ for a directed poset $I$ such that for every $i$ there is $j \geq i$ with $M_i \to M_j$ trace-class. Let $P, Q \in C$ be such that $Q$ and $Q \otimes P$ are compact. Then the map $\hom_C(Q, M \otimes P^{\vee}) \to \hom_C(Q \otimes P, M)$ induced by $M \otimes P^{\vee} \to \iHom(P,M)$ is an equivalence of spectra.
	\end{lemma}

proofs.text:
\begin{proof}
		Apply $\pi_0\Map_C(Q,-)$ to the square of \Cref{lem:Trace_Class_Interleaving}. By adjunction the bottom row now consists of homotopy classes of maps out of $Q\otimes P$. Since $Q$ and $Q\otimes P$ are compact and tensoring with $P^\vee$ preserves colimits, the comparison at $M$ is, on $\pi_0$, the filtered colimit of the vertical comparisons at the stages $M_i$.

		For surjectivity, represent a class by a map $Q\otimes P\to M_i$. Choose a trace-class transition $M_i\to M_j$. The diagonal gives a class in $\pi_0\Map_C(Q,M_j\otimes P^\vee)$, and the lower triangle says it represents the required map at stage $j$.

		For injectivity, take two tensor classes with the same image in the colimit. Pass to a common stage where their images in the bottom row agree, and then choose a trace-class transition out of that stage. Applying the diagonal to the common image gives the same tensor class for both. By the upper triangle this is exactly the image of each original class at the later stage.

		This proves bijectivity on $\pi_0$. Replacing $Q$ by $\Sigma^n Q$ gives the same conclusion on $\pi_n$ for every $n\in\Z$, hence the equivalence of spectra.
	\end{proof}

claims.statement:
\begin{proposition}[Clausen--Scholze; see {\cite[Theorem~8.6]{Clausen_Scholze_Complex_Geometry} and \cite[Propositions~1.27 and~1.28]{Efimov_Inverse_Limits}}]
		\label[proposition]{prop:Nuclear_Basics}
		\leavevmode
		\begin{enumerate}
			\item For $M \in C$, the following are equivalent:
			\begin{enumerate}
				\item[(a)] $M$ is nuclear;
				\item[(b)] for every compact $P$, the map $\hom_C(\unit_C,P^{\vee} \otimes M) \to \hom_C(P,M)$ is an equivalence of spectra (equivalently, since we may replace $P$ by its shifts, the corresponding map of mapping spaces is an equivalence for every compact $P$);
				\item[(d)] $M \simeq \colim_{i \in I} M_i$ for a directed poset $I$ and compact objects $M_i$, such that for every $i$ there is $j \geq i$ with $M_i \to M_j$ trace-class.
			\end{enumerate}
			Moreover, these conditions are implied by
			\begin{enumerate}
				\item[(c)] for every compact $P$, the map $P^{\vee} \otimes M \to \iHom(P,M)$ is an equivalence,
			\end{enumerate}
			and if the tensor product of any two compact objects of $C$ is compact, then (c) is equivalent to (a), (b) and (d).
			\item The subcategory $\Nuc(C) \subseteq C$ is closed under colimits. It is $\omega_1$-presentable, and its $\omega_1$-compact objects are precisely the basic nuclear objects.
		\end{enumerate}
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Nuclear_Definition_Pi0}
		\Cref{prop:Nuclear_Basics} shows that the condition in \Cref{def:Nuclear}, which only asks that the maps $\pi_0\Map_C(\unit_C,P^{\vee} \otimes M) \to \pi_0\Map_C(P,M)$ be surjective, already implies that $\hom_C(\unit_C,P^{\vee} \otimes M) \to \hom_C(P,M)$ is an equivalence. Clausen--Scholze \cite[Definition~8.5]{Clausen_Scholze_Complex_Geometry} instead define nuclearity by the latter condition (and \cite[Definition~13.10]{Scholze_Analytic_Geometry} by an analogous condition for analytic rings), whereas \Cref{def:Nuclear} follows \cite[Definition~1.25]{Efimov_Inverse_Limits}. The two definitions agree; the injectivity comes from the fact that, by (a) $\Rightarrow$ (d), $M$ is a filtered colimit of compact objects along trace-class maps, for which the two sides become interleaved (\Cref{lem:Nuclear_Colimit_Interleaving}).
	\end{remark}

\begin{proposition}[{\cite[Proposition~1.29]{Efimov_Inverse_Limits}}]
		\label[proposition]{prop:Nuclear_Rigid}
		If every trace-class map between compact objects of $C$ factors through a compact object by two trace-class maps, then $C^{\rig}=\Nuc(C)$ as full subcategories of $C$.
	\end{proposition}

proofs.text:
\begin{proof}[Sketch]
		Each of the rationally indexed generators of $C^{\rig}$ from \Cref{sec:Rigidification} is nuclear by \Cref{prop:Nuclear_Basics}(1)(d). Since nuclear objects are closed under colimits, $C^{\rig}\subseteq\Nuc(C)$. Conversely, let $P_0 \to P_1 \to \cdots$ be a sequence of trace-class maps between compact objects. By the assumption and \Cref{lem:Interpolation}(2), applied to $D = C^{\omega}$ and the class of trace-class morphisms (which is closed under composition by \Cref{rem:Trace_Class_Basics}(2)), it extends to a functor $F\colon \Q_{\geq 0} \to C^{\omega}$ with trace-class transition maps and the same colimit. Restricting $F$ to the cofinal subset $\Q_{>0} \cong \Q$, we see that the basic nuclear objects lie in $C^{\rig}$. By \Cref{prop:Nuclear_Basics}(2), these generate $\Nuc(C)$.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Nuclear_Descent}
		On an affinoid adic space the categories of nuclear modules also glue. For a complete sheafy analytic Huber pair $(A,A^+)$, Andreychev proves that $U\mapsto\Nuc(\mathcal O(U))$ satisfies descent for covers by rational opens of $\operatorname{Spa}(A,A^+)$. The same holds after applying continuous K-theory, as recalled in \Cref{thm:Nuclear_Analytic_Descent}.
	\end{remark}

\begin{proposition}[{\cite[Proposition~1.7]{Efimov_Large_Categories}}]
		\label[proposition]{prop:PrLL_Colimits}
		Let $I \to \Pr^{\mathrm{LL}}_{\st}$, $i \mapsto C_i$, be a small diagram, let $C := \colim_i C_i$ be its colimit in $\PrL_{\st}$, and let $F_i\colon C_i \to C$ be the structure functors.
		\begin{enumerate}
			\item The functors $F_i$ are strongly continuous.
			\item A colimit-preserving functor $G\colon C \to D$ to a presentable stable category $D$ is strongly continuous if and only if each composite $G \circ F_i$ is strongly continuous.
		\end{enumerate}
		In particular, $\Pr^{\mathrm{LL}}_{\st}$ is cocomplete, and the inclusion $\Pr^{\mathrm{LL}}_{\st} \to \PrL_{\st}$ preserves colimits.
	\end{proposition}

proofs.text:
\begin{proof}
		We identify $C$ with the limit $\lim_i C_i$ in $\widehat{\Cat}$, taken along the right adjoints $F_{ij}^R$ of the transition functors $F_{ij}$. Under this identification, $F_i^R\colon C \to C_i$ is the projection. Since the transition functors $F_{ij}^R$ preserve colimits, colimits in $\lim_i C_i$ exist and are computed pointwise \cite[Remark~5.4.7.13]{lurie2009HTT}. In particular, the projections $F_i^R$ preserve colimits, which proves (1). Similarly, the right adjoint $G^R\colon D \to C \simeq \lim_i C_i$ corresponds to the compatible family of functors $F_i^RG^R \simeq (GF_i)^R$. As colimits in the limit are computed pointwise, $G^R$ preserves colimits if and only if each $(GF_i)^R$ does, which proves (2).

		For the final assertion, note that $\Map_{\Pr^{\mathrm{LL}}_{\st}}(C,D) \subseteq \Map_{\PrL_{\st}}(C,D)$ is a union of path components, and similarly for the $C_i$. By (2), the equivalence $\Map_{\PrL_{\st}}(C,D) \simeq \lim_i \Map_{\PrL_{\st}}(C_i,D)$ restricts to an equivalence $\Map_{\Pr^{\mathrm{LL}}_{\st}}(C,D) \simeq \lim_i \Map_{\Pr^{\mathrm{LL}}_{\st}}(C_i,D)$, so that $C$, together with the cocone of (1), is also a colimit in $\Pr^{\mathrm{LL}}_{\st}$.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Proposition~2.63]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Prdual_Colimits}
		The full subcategory $\Pr^{\dual} \subseteq \Pr^{\mathrm{LL}}_{\st}$ is closed under small colimits. In particular, $\Pr^{\dual}$ is cocomplete, and the inclusion $\Pr^{\dual} \to \PrL_{\st}$ preserves colimits.
	\end{proposition}

proofs.text:
\begin{proof}
		Let $I \to \Pr^{\dual}$, $i \mapsto C_i$, be a small diagram, and let $C = \colim_i C_i$ in $\PrL_{\st}$. By \Cref{prop:PrLL_Colimits}, it suffices to show that $C$ is dualizable. The structure functors $F_i\colon C_i \to C$ are strongly continuous by \Cref{prop:PrLL_Colimits}(1). Their right adjoints are the projections $\lim_i C_i \to C_i$, which are jointly conservative. Hence the localizing subcategory $L \subseteq C$ generated by the essential images of the $F_i$, which is generated by a set of objects and hence presentable, satisfies $L^{\perp} = 0$. By \Cref{prop:Localization_Sequences_PrL}(1), we get $L = C$. So $C$ is dualizable by \Cref{prop:Generation_Dualizable}.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Propositions~1.13 and~1.14 and Corollary~2.64]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Epimorphisms_Localizations}
		A morphism $F\colon C \to D$ in $\PrL_{\st}$, $\Pr^{\mathrm{LL}}_{\st}$ or $\Pr^{\dual}$ is an epimorphism if and only if it is a localization, i.e.\ $F^R$ is fully faithful.
	\end{proposition}

proofs.text:
\begin{proof}
		A morphism $F\colon C \to D$ in a category with pushouts is an epimorphism if and only if the codiagonal $\nabla\colon D \sqcup_C D \to D$ is an equivalence. By \Cref{prop:PrLL_Colimits,prop:Prdual_Colimits}, pushouts in $\Pr^{\mathrm{LL}}_{\st}$ and $\Pr^{\dual}$ are computed in $\PrL_{\st}$. So it suffices to treat $\PrL_{\st}$.

		Computing the pushout as a pullback along the right adjoints, we have $D \sqcup_C D \simeq D \times_C D$, where both functors $D \to C$ are $F^R$, and the right adjoint of $\nabla$ is the diagonal $\delta\colon D \to D \times_C D$. So $F$ is an epimorphism if and only if $\delta$ is an equivalence. If $F^R$ is fully faithful, then $F^R$ is a monomorphism in $\widehat{\Cat}$, so $\delta$ is an equivalence. Conversely, suppose that $\delta$ is an equivalence, and let $x,y \in D$. Then the map
		\begin{align*}
			\hom_D(x,y) \to \hom_{D \times_C D}(\delta x,\delta y) &\simeq \hom_D(x,y) \times_{\hom_C(F^Rx,F^Ry)} \hom_D(x,y) \\
			&\simeq \hom_D(x,y) \oplus \fib\big(\hom_D(x,y) \to \hom_C(F^Rx,F^Ry)\big)
		\end{align*}
		is the diagonal, and it is an equivalence. Here the splitting of the pullback is induced by the first projection and its section given by the diagonal, so the diagonal corresponds to the inclusion of the first summand. We find that $\hom_D(x,y) \to \hom_C(F^Rx,F^Ry)$ is an equivalence. So $F^R$ is fully faithful.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Monomorphisms_Fully_Faithful}
		Dually, the monomorphisms in $\PrL_{\st}$, in $\Pr^{\mathrm{LL}}_{\st}$ and in $\Pr^{\dual}$ are precisely the fully faithful functors \cite[Propositions~1.13 and~1.14 and Corollary~2.87]{Efimov_Large_Categories}. For $\Pr^{\dual}$, this requires the description of pullbacks in $\Pr^{\dual}$, see \Cref{cor:Monomorphisms_Prdual} below.
	\end{remark}

\begin{remark}
		\label[remark]{rem:Calkin_Small_Vs_Continuous}
		If $C = \Ind(A)$ is compactly generated, the continuous Calkin category $\Calk^{\cont}_{\kappa}(C)$ of \Cref{def:Calkin_Continuous} agrees with $\Calk_{\kappa}(A)$ \cite[Proposition~2.59]{Efimov_Large_Categories}. Indeed, by \Cref{ex:Compactly_Generated_Compactly_Assembled}, the functor $\hat{y}\colon C \to \Ind(C^{\kappa})$ is $\Ind(j)$ for the inclusion $j\colon A \hookrightarrow C^{\kappa} = \Ind(A)^{\kappa}$, so by \Cref{thm:Thomason_Neeman}(1) its cofiber is $\Ind\big((\Ind(A)^{\kappa}/A)^{\idem}\big) = \Ind(\Calk_{\kappa}(A))$.
	\end{remark}

\begin{construction}
		\label[construction]{constr:Calkin_Functoriality}
		Let $F\colon C \to D$ be a strongly continuous functor between dualizable categories. Then $F$ preserves $\kappa$-compact objects, since $F^R$ preserves colimits, so it restricts to a functor $F^{\kappa}\colon C^{\kappa} \to D^{\kappa}$. The left adjoint of $\colim\colon \Ind(C) \to C$ is the composite of $\hat{y}\colon C \to \Ind(C^{\kappa})$ with the inclusion $\Ind(C^{\kappa}) \subseteq \Ind(C)$: indeed, by the proof of \Cref{prop:Dualizable_Further_Characterizations}, the colimit functor of $\Ind(C)$ factors as $\colim_{\kappa} \circ r$, where $r$ is the right adjoint of the inclusion $\Ind(C^{\kappa}) \subseteq \Ind(C)$. Since $\Ind(F)$ restricts to $\Ind(F^{\kappa})$ on $\Ind(C^{\kappa})$, \Cref{prop:Strongly_Continuous_Via_Right_Adjoint} gives a commutative square
		\[
			\begin{tikzcd}
				C \rar["\hat{y}_C"] \dar["F"'] & \Ind(C^{\kappa}) \dar["\Ind(F^{\kappa})"] \\
				D \rar["\hat{y}_D"'] & \Ind(D^{\kappa})
			\end{tikzcd}
		\]
		of strongly continuous functors. Passing to cofibers in $\Pr^{\mathrm{LL}}_{\st}$, which are computed in $\PrL_{\st}$ by \Cref{prop:PrLL_Colimits}, we obtain a strongly continuous functor $\Ind(\Calk^{\cont}_{\kappa}(C)) \to \Ind(\Calk^{\cont}_{\kappa}(D))$. It preserves compact objects, and hence restricts to an exact functor
		\[
			\Calk^{\cont}_{\kappa}(F)\colon \Calk^{\cont}_{\kappa}(C) \to \Calk^{\cont}_{\kappa}(D).
		\]
		The squares above are coherent in $F$: the colimit functors form a natural transformation $\Ind((-)^{\kappa}) \to \id$, and taking mates along $\hat{y}_C \dashv \colim_C$ gives the natural maps $\hat{y}_D F \to \Ind(F^{\kappa})\hat{y}_C$ used above. These are isomorphisms for strongly continuous $F$, by \Cref{prop:Strongly_Continuous_Via_Right_Adjoint}. The compatibility of mates with composition supplies a natural transformation $\id \to \Ind((-)^{\kappa})$ in $\Pr^{\mathrm{LL}}_{\st}$. Applying the cofiber functor and then taking compact objects therefore defines a functor $\Calk^{\cont}_{\kappa}\colon \Pr^{\dual} \to \Cat_{\perf}$, including its higher coherences.

		Under the identifications of the quotients with kernels, the functor $\Ind(\Calk^{\cont}_{\kappa}(C)) \to \Ind(\Calk^{\cont}_{\kappa}(D))$ is the restriction of $\Ind(F^{\kappa})$. Indeed, the functors $\colim_D \circ \Ind(F^{\kappa})$ and $F \circ \colim_C$ preserve colimits and agree on $C^{\kappa}$, so $\Ind(F^{\kappa})$ maps $\ker(\colim_C)$ into $\ker(\colim_D)$. The left adjoint $q_C$ of the inclusion $\ker(\colim_C) \subseteq \Ind(C^{\kappa})$ is given by $q_C(X) = \cofib(\hat{y}_C\colim_C X \to X)$. Using the square above, we get $\Ind(F^{\kappa})(q_CX) \simeq q_D(\Ind(F^{\kappa})X)$, which identifies the functor induced on the quotients with the restriction of $\Ind(F^{\kappa})$.
	\end{construction}

\begin{definition}
		\label[definition]{def:Short_Exact_Sequence_Dualizable}
		A \emph{short exact sequence} of dualizable categories is a strongly continuous localization sequence $C \to D \to E$ in $\PrL_{\st}$ (\Cref{def:Localization_Sequence_PrL}) in which $C$, $D$ and $E$ are dualizable. Equivalently, it is a sequence in $\Pr^{\dual}$ which is both a fiber sequence and a cofiber sequence in $\PrL_{\st}$ (\Cref{prop:Localization_Sequences_PrL}).
	\end{definition}

\begin{proposition}[{\cite[Proposition~2.61]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Calkin_Short_Exact}
		The functor $\Calk^{\cont}_{\kappa}\colon \Pr^{\dual} \to \Cat_{\perf}$ sends short exact sequences of dualizable categories to short exact sequences.
	\end{proposition}

proofs.text:
\begin{proof}
		Let $C \xrightarrow{F} D \xrightarrow{G} E$ be a short exact sequence of dualizable categories. As shown above, $C$ and $D$ are $\kappa$-compactly generated. Since $G$ preserves $\kappa$-compact objects, \cite[Proposition~A.26]{Ramzi_Dualizable_Presentable} shows that $C^{\kappa} \to D^{\kappa} \to E^{\kappa}$ is a short exact sequence. By \Cref{thm:Thomason_Neeman}(1), the sequence $\Ind(C^{\kappa}) \to \Ind(D^{\kappa}) \to \Ind(E^{\kappa})$ is a strongly continuous localization sequence. By \Cref{constr:Calkin_Functoriality}, we obtain a commutative diagram
		\[
			\begin{tikzcd}
				C \rar["\hat{y}"] \dar["F"'] & \Ind(C^{\kappa}) \rar \dar & \Ind(\Calk^{\cont}_{\kappa}(C)) \dar["\Phi"] \\
				D \rar["\hat{y}"] \dar["G"'] & \Ind(D^{\kappa}) \rar \dar & \Ind(\Calk^{\cont}_{\kappa}(D)) \dar \\
				E \rar["\hat{y}"'] & \Ind(E^{\kappa}) \rar & \Ind(\Calk^{\cont}_{\kappa}(E))
			\end{tikzcd}
		\]
		in which the rows and the first two columns are cofiber sequences in $\PrL_{\st}$. Since colimits commute with colimits, the third column is a cofiber sequence in $\PrL_{\st}$ as well.

		We claim that $\Phi$ is fully faithful. By \Cref{constr:Calkin_Functoriality}, $\Phi$ is identified with the restriction of $\Ind(F^{\kappa})$ to the kernels of the colimit functors. Since $F$ is fully faithful, so are $F^{\kappa}$ and $\Ind(F^{\kappa})$, and hence so is $\Phi$.

		Since $\Phi$ is fully faithful and colimit-preserving, its essential image is closed under colimits, and the cofiber sequence of the third column is a localization sequence by \Cref{prop:Localization_Sequences_PrL}(1). All functors involved preserve compact objects, so it is strongly continuous. By \Cref{thm:Thomason_Neeman}(2), the sequence $\Calk^{\cont}_{\kappa}(C) \to \Calk^{\cont}_{\kappa}(D) \to \Calk^{\cont}_{\kappa}(E)$ of compact objects is short exact.
	\end{proof}

claims.statement:
\begin{lemma}[{\cite[Proposition~2.65]{Efimov_Large_Categories}}]
		\label[lemma]{lem:Filtered_Colimits_PrL}
		Let $I$ be a directed poset, let $I \to \PrL_{\st}$, $i \mapsto C_i$, be a diagram with transition functors $F_{ij}\colon C_i \to C_j$, let $C := \colim_i C_i$ in $\PrL_{\st}$, and let $F_i\colon C_i \to C$ be the structure functors.
		\begin{enumerate}
			\item The counits induce an equivalence $\colim_i F_iF_i^R \simeq \id_C$.
			\item If the functors $F_{ij}$ are strongly continuous, then for all $i,j \in I$ there is a natural equivalence
			\[
				\colim_{k \geq i,j} F_{jk}^RF_{ik} \simeq F_j^RF_i.
			\]
		\end{enumerate}
	\end{lemma}

\begin{proposition}[{\cite[Proposition~2.67]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Filtered_Colimits_Fully_Faithful}
		\leavevmode
		\begin{enumerate}
			\item In $\Pr^{\mathrm{LL}}_{\st}$ and in $\Pr^{\dual}$, the class of fully faithful functors is closed under filtered colimits.
			\item A filtered colimit of strongly continuous localization sequences, formed in $\PrL_{\st}$, is again a strongly continuous localization sequence. In particular, filtered colimits of short exact sequences of dualizable categories are short exact.
		\end{enumerate}
	\end{proposition}

proofs.text:
\begin{proof}
		(1) By \Cref{prop:Prdual_Colimits}, it suffices to treat $\Pr^{\mathrm{LL}}_{\st}$. Let $I$ be a directed poset, let $(C_i)$ and $(D_i)$ be $I$-indexed diagrams in $\Pr^{\mathrm{LL}}_{\st}$ with transition functors $F_{ij}$ and $G_{ij}$, and let $\Phi_i\colon C_i \to D_i$ be a natural transformation whose components are fully faithful and strongly continuous. Let $C = \colim_i C_i$ and $D = \colim_i D_i$, with structure functors $F_i$ and $G_i$, and let $\Phi\colon C \to D$ be the induced functor, which is strongly continuous by \Cref{prop:PrLL_Colimits}. We show that the unit $\id_C \to \Phi^R\Phi$ is an equivalence. Both functors preserve colimits, the essential images of the $F_i$ generate $C$ under colimits, and the functors $F_j^R$ are jointly conservative (see the proof of \Cref{prop:Prdual_Colimits}). So it suffices to show that $F_j^RF_i \to F_j^R\Phi^R\Phi F_i$ is an equivalence for all $i,j \in I$. Using $\Phi F_i \simeq G_i\Phi_i$, \Cref{lem:Filtered_Colimits_PrL}(2), the strong continuity of $\Phi_j$ and the fully faithfulness of $\Phi_k$, we compute
		\begin{align*}
			F_j^R\Phi^R\Phi F_i &\simeq \Phi_j^RG_j^RG_i\Phi_i \simeq \Phi_j^R\Big(\colim_{k \geq i,j} G_{jk}^RG_{ik}\Big)\Phi_i \simeq \colim_{k \geq i,j} \Phi_j^RG_{jk}^RG_{ik}\Phi_i \\
			&\simeq \colim_{k \geq i,j} F_{jk}^R\Phi_k^R\Phi_kF_{ik} \simeq \colim_{k \geq i,j} F_{jk}^RF_{ik} \simeq F_j^RF_i.
		\end{align*}
		More precisely, under the canonical cocones in \Cref{lem:Filtered_Colimits_PrL}(2), the map $F_j^RF_i \to F_j^R\Phi^R\Phi F_i$ is the colimit of the maps
		\[
			F_{jk}^RF_{ik} \longrightarrow F_{jk}^R\Phi_k^R\Phi_kF_{ik}
		\]
		induced by the units of $\Phi_k \dashv \Phi_k^R$. This follows by pasting the adjunction units for the squares $\Phi_kF_{ik} \simeq G_{ik}\Phi_i$ and for the colimit cocones. Each of these maps is an isomorphism because $\Phi_k$ is fully faithful, so their colimit is an isomorphism as required.

		(2) Let $C_i \to D_i \to E_i$ be a filtered diagram of strongly continuous localization sequences, and let $C \to D \to E$ be its colimit in $\PrL_{\st}$. By \Cref{prop:PrLL_Colimits}, it is a sequence of strongly continuous functors. Since colimits commute with colimits, $D \to E$ is the cofiber of $C \to D$ in $\PrL_{\st}$. By (1), $C \to D$ is fully faithful, and it preserves colimits. Hence $C \to D \to E$ is a localization sequence by \Cref{prop:Localization_Sequences_PrL}(1). If the $D_i$ are dualizable, then so is $D$ by \Cref{prop:Prdual_Colimits}.
	\end{proof}

claims.statement:
\begin{corollary}[{\cite[Corollary~2.68]{Efimov_Large_Categories}}]
		\label[corollary]{cor:Filtered_Union_Subcategories}
		Let $C$ be a presentable stable category, and let $(C_i)_{i \in I}$ be a directed family of presentable stable full subcategories $C_i \subseteq C$ whose inclusion functors are strongly continuous. If $C$ is generated under colimits by the $C_i$, then the functor $\colim_i C_i \to C$ is an equivalence, where the colimit is formed in $\PrL_{\st}$.
	\end{corollary}

proofs.text:
\begin{proof}
		For $i \leq j$, the right adjoint of $C_i \hookrightarrow C_j$ is the restriction of the right adjoint of $C_i \hookrightarrow C$, so the transition functors are strongly continuous. The colimit of the constant diagram with value $C$ over the weakly contractible poset $I$ is $C$. Applying \Cref{prop:Filtered_Colimits_Fully_Faithful}(1) to the inclusions $C_i \hookrightarrow C$ shows that $\colim_i C_i \to C$ is fully faithful. Its essential image is closed under colimits and contains all $C_i$, so it is all of $C$.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Filtered_Colimits_Fail_PrL}
		\Cref{prop:Filtered_Colimits_Fully_Faithful} and \Cref{cor:Filtered_Union_Subcategories} fail in $\PrL_{\st}$, i.e.\ without the strong continuity assumptions. Efimov \cite[Remark~2.69]{Efimov_Large_Categories} considers $C = \D(\Z)$ and $C_n = \D(\Z[p_k^{-1} \mid k \geq n]) \subseteq C$, where $p_k$ is the $k$-th prime number. The subcategories $C_1 \subseteq C_2 \subseteq \cdots$ generate $C$ under colimits, but $\colim_n C_n \to C$ is not an equivalence, as one shows using \Cref{lem:Filtered_Colimits_PrL}(1).
	\end{remark}

\begin{proposition}[{\cite[Proposition~2.70]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Compact_Objects_Filtered_Colimits}
		The functor $(-)^{\omega}\colon \Pr^{\dual} \to \Cat_{\perf}$ preserves filtered colimits. In particular, $\Sp$ is a compact object of $\Pr^{\dual}$.
	\end{proposition}

\begin{proposition}[{\cite[Proposition~2.81]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Q_Exhaustion}
		Let $C$ be a dualizable category and let $x \in C^{\omega_1}$. Then there exists a functor $\Phi\colon (\Q,\leq) \to C$ such that
		\begin{enumerate}
			\item $\colim_{a \in \Q} \Phi(a) \simeq x$;
			\item for every $a \in \Q$, the canonical map $\colim_{b < a} \Phi(b) \to \Phi(a)$ is an equivalence;
			\item for all $a < b$ in $\Q$, the morphism $\Phi(a) \to \Phi(b)$ is compact.
		\end{enumerate}
	\end{proposition}

\begin{lemma}[{\cite[Lemma~2.82]{Efimov_Large_Categories}}]
		\label[lemma]{lem:Largest_Dualizable_Subcategory}
		Let $C$ be a dualizable category, and let $D \subseteq C$ be a full stable subcategory closed under colimits. Then there is a largest full subcategory $E \subseteq D$ such that $E$ is dualizable and the inclusion $E \hookrightarrow C$ is strongly continuous. Moreover, $E$ is generated under colimits by the objects $\colim_{\Q} F$, where $F\colon \Q \to D$ is a functor such that $F(a) \to F(b)$ is compact in $C$ for all $a < b$.
	\end{lemma}

\begin{remark}
		\label[remark]{rem:Dualizable_Coreflection}
		Efimov also shows that the inclusion $\Pr^{\dual} \hookrightarrow \Pr^{\mathrm{LL}}_{\st}$ admits a right adjoint \cite[Remark~2.57]{Efimov_Large_Categories}: for a presentable stable category $C$, the strictly full dualizable subcategories of $C$ with strongly continuous inclusion form a small complete lattice, whose join is given by images of products in the sense of \Cref{def:Image_Functor} (using \Cref{cor:Image_Dualizable} and \Cref{rem:Products_Dualizable}). Its largest element is the value of the right adjoint at $C$.
	\end{remark}

\begin{definition}
		\label[definition]{def:Dualizable_Kernel}
		Let $F\colon C \to D$ be a strongly continuous functor between dualizable categories, and let $\ker(F) \subseteq C$ be its kernel in $\PrL_{\st}$. The \emph{dualizable kernel} $\ker^{\dual}(F) \subseteq \ker(F)$ is the largest full subcategory of $\ker(F)$ which is dualizable and whose inclusion into $C$ is strongly continuous; it exists by \Cref{lem:Largest_Dualizable_Subcategory}.
	\end{definition}

\begin{proposition}[{\cite[Proposition~2.83]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Dualizable_Kernel}
		Let $F\colon C \to D$ be a strongly continuous functor between dualizable categories. Then $\ker^{\dual}(F) \to C \xrightarrow{F} D$ is a fiber sequence in $\Pr^{\dual}$.
	\end{proposition}

proofs.text:
\begin{proof}
		Write $j\colon \ker^{\dual}(F) \hookrightarrow C$ for the inclusion. Let $T$ be dualizable and let $G\colon T \to C$ be strongly continuous with $FG \simeq 0$. Then $\Im(G) \subseteq \ker(F)$, and by \Cref{cor:Image_Dualizable}, $\Im(G)$ is dualizable and its inclusion into $C$ is strongly continuous. By maximality, $\Im(G) \subseteq \ker^{\dual}(F)$, so $G \simeq jG'$ for a colimit-preserving functor $G'\colon T \to \ker^{\dual}(F)$. Its right adjoint $G^Rj$ preserves colimits, so $G'$ is strongly continuous. Since $j$ is fully faithful, $j \circ -$ identifies $\Map_{\Pr^{\dual}}(T,\ker^{\dual}(F))$ with the union of those path components of $\Map_{\Pr^{\dual}}(T,C)$ which consist of functors $G$ with $FG \simeq 0$. Since a nullhomotopy of $FG$ is unique if it exists (\Cref{rem:Nullhomotopies_Property}), the latter is the fiber of $F \circ -\colon \Map_{\Pr^{\dual}}(T,C) \to \Map_{\Pr^{\dual}}(T,D)$ over the zero functor.
	\end{proof}

claims.statement:
\begin{example}[{\cite[Example~2.84]{Efimov_Large_Categories}}]
		\label[example]{ex:Dualizable_Kernel_DVR}
		Let $R$ be a discrete valuation ring with maximal ideal $\mathfrak{m}$ and fraction field $K$, and consider the base change functor $F\colon \D(R) \to \D(R/\mathfrak{m})$, which is strongly continuous. Its kernel in $\PrL_{\st}$ consists of the $R$-modules on which a uniformizer acts invertibly, i.e.\ $\ker(F) \simeq \D(K)$. However, the inclusion $\D(K) \hookrightarrow \D(R)$ is not strongly continuous, since its right adjoint $\hom_R(K,-)$ does not preserve colimits, $K$ not being a compact $R$-module. The only localizing subcategories of $\D(K)$ are $0$ and $\D(K)$, so $\ker^{\dual}(F) = 0$.
	\end{example}

\begin{proposition}[{\cite[Proposition~2.86]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Dualizable_Pullbacks}
		Let $F\colon A \to C$ and $G\colon B \to C$ be strongly continuous functors between dualizable categories, and let $A \times_C^{\dual} B := \ker^{\dual}(\Phi)$, with $\Phi$ as above.
		\begin{enumerate}
			\item The category $A \times^{\dual}_C B$ is a pullback of $F$ and $G$ in $\Pr^{\dual}$. The functor $A \times^{\dual}_C B \to A \times_C B$ is fully faithful and strongly continuous, and its essential image is the largest full subcategory $E \subseteq A \times_C B$ such that $E$ is dualizable and the functors $E \to A$ and $E \to B$ are strongly continuous.
			\item If $G$ is a localization, then $A \times^{\dual}_C B \simeq A \times_C B$, and the projection $A \times_C B \to A$ is a localization.
		\end{enumerate}
	\end{proposition}

\begin{corollary}[{\cite[Corollary~2.87]{Efimov_Large_Categories}}]
		\label[corollary]{cor:Monomorphisms_Prdual}
		A strongly continuous functor $F\colon C \to D$ between dualizable categories is a monomorphism in $\Pr^{\dual}$ if and only if it is fully faithful.
	\end{corollary}

proofs.text:
\begin{proof}
		If $F$ is fully faithful, then $F \circ -$ is fully faithful on functor categories, so it induces monomorphisms on mapping spaces. Conversely, if $F$ is a monomorphism, then the diagonal $C \to C \times^{\dual}_D C$ is an equivalence. Composing with the fully faithful functor $C \times^{\dual}_D C \to C \times_D C$ of \Cref{prop:Dualizable_Pullbacks}(1), we find that the diagonal $C \to C \times_D C$ is fully faithful. As in the proof of \Cref{prop:Epimorphisms_Localizations}, it follows that $\hom_C(x,y) \to \hom_D(Fx,Fy)$ is an equivalence for all $x,y \in C$.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Short_Exact_Fiber_Cofiber}
		A short exact sequence $C \xrightarrow{i} D \xrightarrow{p} E$ of dualizable categories (\Cref{def:Short_Exact_Sequence_Dualizable}) is both a fiber sequence and a cofiber sequence in $\Pr^{\dual}$. It is a cofiber sequence since colimits in $\Pr^{\dual}$ are computed in $\PrL_{\st}$ (\Cref{prop:Prdual_Colimits}). It is a fiber sequence since $\ker^{\dual}(p) = \ker(p) = C$, as the inclusion $C \hookrightarrow D$ is strongly continuous; alternatively, apply \Cref{prop:Dualizable_Pullbacks}(2) to the functors $0 \to E$ and $p$.
	\end{remark}

\begin{proposition}[{\cite[Proposition~2.89]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Dualizable_Ind_Adjunction}
		The inclusion $\Pr^{\dual} \to \PrL_{\st,\kappa}$ admits a right adjoint $R_{\kappa}$, given by $R_{\kappa}(D) = \Ind(D^{\kappa})$ and $R_{\kappa}(F) = \Ind(F^{\kappa})$.
	\end{proposition}

\begin{lemma}[{\cite[Proposition~2.99 and Corollary~2.100]{Efimov_Large_Categories}}]
		\label[lemma]{lem:Products_Ind_Comparison}
		\leavevmode
		\begin{enumerate}
			\item Under the identification $\Ind(A) \simeq \Fun^{\ex}(A\catop,\Sp)$ of \Cref{cor:Ind_As_Exact_Functors}, we have $P_A((X_i)_i)\big((a_i)_i\big) \simeq \prod_i X_i(a_i)$.
			\item If $X_i \simeq \quotcolim_{j \in J_i} a_{i,j}$ for filtered categories $J_i$, then $P_A((X_i)_i) \simeq \quotcolim_{(j_i)_i \in \prod_i J_i} (a_{i,j_i})_i$. In particular, $y((a_i)_i) \simeq P_A((y(a_i))_i)$.
			\item For exact functors $F_i\colon A_i \to B_i$ with product $F := \prod_i F_i$, we have $\Ind(F) \circ P_A \simeq P_B \circ \prod_i \Ind(F_i)$ and $\Ind(F)^R \circ P_B \simeq P_A \circ \prod_i \Ind(F_i)^R$.
		\end{enumerate}
	\end{lemma}

proofs.text:
\begin{proof}
		(1) The right adjoint of $\Ind(\mathrm{pr}_i)$ is restriction along $\mathrm{pr}_i$, and the right adjoint of a functor into a product is the product of the right adjoints of its components.

		(2) Evaluating at $(b_i)_i \in A$ and using that filtered colimits in $\Fun^{\ex}(A\catop,\Sp)$ are computed pointwise, the claim becomes $\colim_{(j_i)_i} \prod_i \hom_{A_i}(b_i,a_{i,j_i}) \simeq \prod_i \colim_{j \in J_i}\hom_{A_i}(b_i,a_{i,j})$, which is (AB6) in $\Sp$ (\Cref{prop:Dualizable_AB6}). This is also a special case of \Cref{lem:Products_In_Ind}.

		(3) The first equivalence follows from (2), since $\Ind(F)$ and $\Ind(F_i)$ are computed on filtered presentations levelwise. For the second, pass to left adjoints: the left adjoint of $\Ind(F)^R \circ P_B$ is the functor $\Ind(A) \to \prod_i \Ind(B_i)$ with components $\Ind(\mathrm{pr}_i)\Ind(F) \simeq \Ind(F_i)\Ind(\mathrm{pr}_i)$, which is also the left adjoint of $P_A \circ \prod_i \Ind(F_i)^R$.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Proposition~2.102]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Products_Small_Projections}
		Let $(F_i\colon A_i \to B_i)_{i \in I}$ be a family of exact functors in $\Cat_{\perf}$, and put $F := \prod_i F_i$.
		\begin{enumerate}
			\item If each $K_i \to A_i \xrightarrow{F_i} B_i$ is a short exact sequence, then so is $\prod_i K_i \to \prod_i A_i \xrightarrow{F} \prod_i B_i$.
			\item If each $F_i$ is a homological epimorphism, then so is $F$. Moreover, $\ker(\Ind(F))$ is generated under colimits by the objects $P_A((X_i)_i)$ with $X_i \in \ker(\Ind(F_i))$.
		\end{enumerate}
	\end{proposition}

proofs.text:
\begin{proof}
		The quotient functors $p_i\colon C_i^{\kappa} \to \Calk^{\cont}_{\kappa}(C_i)$ are homological epimorphisms, since $\Ind(p_i)$ is the localization in the Calkin sequence of $C_i$. By \Cref{prop:Products_Small_Projections}(2), the functor $\Ind(\prod_i p_i)$ is a strongly continuous localization. By \Cref{lem:Strong_Continuity_Localization_Sequence} and \Cref{prop:Localization_Sequence_Dualizable}, its kernel is dualizable with strongly continuous inclusion, so it agrees with the dualizable kernel, which is $\prod^{\dual}_i C_i$ by \Cref{thm:General_Limits_Dualizable}.

		If each $C_i$ is compactly generated, then $C_i^{\omega} \to C_i^{\kappa} \to \Calk^{\cont}_{\kappa}(C_i)$ is short exact by \Cref{rem:Calkin_Small_Vs_Continuous}. By \Cref{prop:Products_Small_Projections}(1), their product is short exact, and applying \Cref{thm:Thomason_Neeman}(1) identifies the kernel of $\Ind(\prod_i p_i)$ with $\Ind(\prod_i C_i^{\omega})$.
	\end{proof}

claims.statement:
\begin{lemma}[{\cite[Section~2.5]{Efimov_Large_Categories}}]
		\label[lemma]{lem:Duality_Localizations}
		Let $F\colon C \to D$ be a strongly continuous functor between dualizable categories. Then $(F^R)^{\vee}$ is left adjoint to $F^{\vee}$, and $F$ is a localization if and only if $F^{\vee}$ is fully faithful. If $F$ is fully faithful, then so is $(F^R)^{\vee}$.
	\end{lemma}

proofs.text:
\begin{proof}
		For an adjunction $L \dashv R$, precomposition with $R$ is left adjoint to precomposition with $L$, with unit and counit induced by those of $L \dashv R$. Applied to $F \dashv F^R$, this shows $(F^R)^{\vee} \dashv F^{\vee}$, with counit $\varphi \circ FF^R \to \varphi$ induced by the counit of $F \dashv F^R$. If $F$ is a localization, this counit is an equivalence, so $F^{\vee}$ is fully faithful. Conversely, if $F^{\vee}$ is fully faithful, then $\varphi(FF^Rd) \to \varphi(d)$ is an equivalence for all $\varphi \in D^{\vee}$ and $d \in D$. Since $D$ is dualizable, the functor $D \to \Fun^{\colim}(D^{\vee},\Sp)$, $d \mapsto (\varphi \mapsto \varphi(d))$, is an equivalence, so $FF^Rd \to d$ is an equivalence. Similarly, if $F$ is fully faithful, then the unit $\varphi \to \varphi F^RF$ of $(F^R)^{\vee} \dashv F^{\vee}$ is an equivalence.
	\end{proof}

\begin{proof}
		The functor $\Phi$ is fully faithful by \Cref{lem:Duality_Localizations}. Let $p := \Ind(\prod_i p_i)$ be the localization of \Cref{cor:Products_Dualizable_Calkin}. For $X \in \Ind(\prod_i C_i^{\kappa})$ we have a cofiber sequence $jj^RX \to X \to p^Rp X$. Since $\Phi$ is fully faithful with right adjoint $j^{\vee}$, its essential image consists of those $\varphi$ for which the counit $\varphi jj^R \to \varphi$ is an equivalence, i.e.\ for which $\varphi p^R \simeq 0$. By the discussion preceding \Cref{lem:Duality_Localizations}, $(p^R)^{\vee}$, as the left adjoint of $p^{\vee}$, is identified with $\Ind(\prod_i p_i\catop)$. So the essential image of $\Phi$ is $\ker(\Ind(\prod_i p_i\catop))$. The same argument for a single $C_i$ identifies $C_i^{\vee}$, via $(\hat{y}^R)^{\vee} = - \circ \colim$, with $\ker(\Ind(p_i\catop))$; this sends $x$ to $x \circ \colim$, whose restriction to $C_i^{\kappa}$ is $x|_{C_i^{\kappa}}$.

		A functor $f$ in $\Cat_{\perf}$ is a homological epimorphism if and only if it is an epimorphism in $\Cat_{\perf}$: indeed, $\Ind\colon \Cat_{\perf} \to \PrL_{\omega,\st}$ is an equivalence, pushouts in $\PrL_{\omega,\st}$ are computed in $\PrL_{\st}$ (as in \Cref{prop:Prdual_Colimits}), and we can apply \Cref{prop:Epimorphisms_Localizations}. Since $(-)\catop$ is an automorphism of $\Cat_{\perf}$, the functors $p_i\catop$ are homological epimorphisms as well \cite[Remark~1.10]{Efimov_Large_Categories}. By \Cref{prop:Products_Small_Projections}(2), the kernel of $\Ind(\prod_i p_i\catop)$ is generated by applying the product comparison functor of \Cref{lem:Products_Ind_Comparison} to families of these restrictions $x_i|_{C_i^{\kappa}}$. Its pointwise formula gives exactly the functors $E_x$.
	\end{proof}

claims.statement:
\begin{proposition}[{\cite[Propositions~2.105 and~2.106]{Efimov_Large_Categories}}]
		\label[proposition]{prop:Exact_Products_AB6_Dualizable}
		Products in $\Pr^{\dual}$ of short exact sequences of dualizable categories are short exact, and $\Pr^{\dual}$ satisfies (AB6): for filtered categories $J_i$, $i \in I$, and functors $J_i \to \Pr^{\dual}$, $j \mapsto C_{i,j}$, the comparison functor
		\[
			\colim_{(j_i)_i \in \prod_i J_i} \prod\nolimits^{\dual}_i C_{i,j_i} \to \prod\nolimits^{\dual}_i \colim_{j \in J_i} C_{i,j}
		\]
		is an equivalence, where the colimits are computed in $\Pr^{\dual}$.
	\end{proposition}

\begin{definition}
		\label[definition]{def:Kappa_Filtered}
		We use the quasicategory model to specify the size of diagram shapes: a simplicial set is \emph{$\kappa$-small} if it has fewer than $\kappa$ nondegenerate simplices. A category $I$ is \emph{$\kappa$-filtered} if every diagram $K\to I$ indexed by a $\kappa$-small simplicial set extends to a cocone $K^{\triangleright}\to I$. This property is independent of the chosen model of $I$. The phrases \emph{$\kappa$-small limit} and \emph{$\kappa$-small colimit} likewise refer to these diagram shapes. We say \emph{filtered} for $\omega$-filtered. A colimit indexed by a small $\kappa$-filtered category is called a \emph{$\kappa$-filtered colimit}.
	\end{definition}

\begin{definition}
		\label[definition]{def:Kappa_Compact}
		Let $C$ be a category which admits $\kappa$-filtered colimits. An object $x \in C$ is called \emph{$\kappa$-compact} if the functor $\Map_C(x,-)\colon C \to \An$ preserves $\kappa$-filtered colimits. We write $C^{\kappa} \subseteq C$ for the full subcategory of $\kappa$-compact objects, and say \emph{compact} for $\omega$-compact.
	\end{definition}

\begin{corollary}
		\label[corollary]{cor:Kappa_Small_Colimits_Of_Kappa_Compacts}
		Let $C$ be a category with $\kappa$-filtered colimits.
		\begin{enumerate}
			\item If $\kappa \leq \lambda$, then every $\kappa$-compact object of $C$ is $\lambda$-compact.
			\item If $C$ admits $\kappa$-small colimits, then $C^{\kappa} \subseteq C$ is closed under $\kappa$-small colimits.
			\item Let $x \in C$ and let $u\colon \Map_C(x,-) \to \Map_C(x',-)$ exhibit $\Map_C(x,-)$ as a retract of $\Map_C(x',-)$ in $\Fun(C,\An)$. If $x'$ is $\kappa$-compact, then so is $x$. In particular, $C^{\kappa}$ is closed under retracts.
		\end{enumerate}
	\end{corollary}

proofs.text:
\begin{proof}
		(1) A $\lambda$-filtered category is $\kappa$-filtered.

		(2) If $x = \colim_{k \in K} x_k$ with $K$ $\kappa$-small and each $x_k$ $\kappa$-compact, then $\Map_C(x,-) = \lim_{k \in K\catop} \Map_C(x_k,-)$ is a $\kappa$-small limit of functors preserving $\kappa$-filtered colimits, hence preserves $\kappa$-filtered colimits by \Cref{thm:Filtered_Colimits_Commute_With_Small_Limits}.

		(3) A retract of a functor preserving $\kappa$-filtered colimits again preserves them, since a retract of an equivalence in $\An$ (namely the comparison map from the colimit) is an equivalence.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Kappa_Filtered_Posets}
		A partially ordered set $P$ is $\kappa$-filtered if and only if every subset $S \subseteq P$ of cardinality $< \kappa$ admits an upper bound in $P$. In particular, $P$ is filtered if and only if it is non-empty and every two elements admit a common upper bound.
	\end{lemma}

proofs.text:
\begin{proof}
		Suppose $P$ is $\kappa$-filtered and let $S \subseteq P$ have cardinality $< \kappa$. Regarding $S$ as a discrete category, the inclusion $S \to P$ is a $\kappa$-small diagram, and a cocone on it is precisely an upper bound of $S$.

		Conversely, let $F\colon K \to P$ be a functor with $K$ $\kappa$-small. Then $K$ has fewer than $\kappa$ objects up to equivalence, so the image $S$ of $F$ on objects has cardinality $< \kappa$. Choose an upper bound $u$ of $S$. Since $\Fun(K,P)$ is again a partially ordered set, in which $F \leq G$ if and only if $F(k) \leq G(k)$ for all $k$, there is a (unique) natural transformation from $F$ to the constant functor with value $u$, i.e.\ a cocone on $F$.

		For the last statement, note that every finite subset of $P$ has an upper bound if and only if $P$ is non-empty and every two elements have an upper bound, by induction on the size of the subset.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Omega_1_Filtered_Via_Chains}
		A filtered partially ordered set $P$ is $\omega_1$-filtered if and only if every increasing sequence $p_0 \leq p_1 \leq p_2 \leq \dots$ in $P$ admits an upper bound.
	\end{lemma}

proofs.text:
\begin{proof}
		The condition is clearly necessary. Conversely, let $S = \{s_0,s_1,s_2,\dots\} \subseteq P$ be a countable subset (a finite subset has an upper bound since $P$ is filtered). Using that $P$ is filtered, choose inductively $p_0 \geq s_0$ and $p_n \geq p_{n-1}, s_n$ for $n \geq 1$. Then an upper bound for the increasing sequence $(p_n)_n$ is an upper bound for $S$. We conclude by \Cref{lem:Kappa_Filtered_Posets}.
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Cofinality_Posets}
		Let $f\colon A \to B$ be a map of partially ordered sets such that for every $b \in B$ the subset $\{a \in A \mid b \leq f(a)\} \subseteq A$ is non-empty and filtered. Then $f$ is cofinal. In particular:
		\begin{enumerate}
			\item A map $f\colon \N \to B$ into a partially ordered set is cofinal if for every $b \in B$ there exists $n$ with $b \leq f(n)$.
			\item Every countable filtered partially ordered set $Q$ admits a cofinal map $\N \to Q$.
			\item The diagonal $\N \to \N \times \N$ is cofinal, and so is every map $f\colon \N \to \N$ with $f(n) \geq n$ for all $n$.
		\end{enumerate}
	\end{lemma}

proofs.text:
\begin{proof}
		The first statement was explained above. For (1), the subset $\{n \mid b \leq f(n)\}$ is non-empty and upwards closed in $\N$ (as $f$ is order preserving), hence of the form $\{n \geq n_0\}$, which is filtered. For (2), if $Q$ is finite it has a largest element (\Cref{lem:Kappa_Filtered_Posets}) and we may take the constant map. Otherwise enumerate $Q = \{q_0,q_1,\dots\}$ and choose inductively $f(0) = q_0$ and $f(n) \geq f(n-1), q_n$; then $f$ is order preserving and cofinal by (1). Statement (3) follows directly from (1).
	\end{proof}

claims.statement:
\begin{theorem}[{\cite[Proposition~5.3.1.18]{lurie2009HTT}}]
		\label[theorem]{thm:Filtered_Posets_Cofinal}
		For every $\kappa$-filtered category $I$ there exist a $\kappa$-filtered partially ordered set $P$ and a cofinal functor $P \to I$.
	\end{theorem}

\begin{proposition}
		\label[proposition]{prop:Colimits_Over_Countable_Subposets}
		Let $P$ be a filtered partially ordered set, and let $\Sigma$ be the set of countable filtered subsets $Q \subseteq P$, ordered by inclusion. Then $\Sigma$ is $\omega_1$-filtered and $P = \bigcup_{Q \in \Sigma} Q$. Moreover, for every functor $F\colon P \to D$ into a category with filtered colimits, there is a natural equivalence
		\[
			\colim_{p \in P} F(p) \simeq \colim_{Q \in \Sigma} \colim_{q \in Q} F(q).
		\]
	\end{proposition}

proofs.text:
\begin{proof}
		Every $p \in P$ lies in the countable filtered subset $\{p\}$. Let $Q_0,Q_1,\dots \in \Sigma$ be countably many elements. Put $U_0 = \bigcup_n Q_n$ (and add one element of $P$ if the family is empty), and inductively let $U_{k+1} \supseteq U_k$ be obtained by adding a chosen common upper bound in $P$ for every pair of elements of $U_k$. Then $U = \bigcup_k U_k$ is countable, and any two elements of $U$ have an upper bound in $U$; hence $U \in \Sigma$ by \Cref{lem:Kappa_Filtered_Posets}, and $U$ is an upper bound of the $Q_n$. So $\Sigma$ is $\omega_1$-filtered by \Cref{lem:Kappa_Filtered_Posets}.

		Consider the partially ordered set $E = \{(Q,q) \mid Q \in \Sigma, q \in Q\}$, with $(Q,q) \leq (Q',q')$ if $Q \subseteq Q'$ and $q \leq q'$, together with the projections $\pi\colon E \to \Sigma$ and $\rho\colon E \to P$. The map $\rho$ is cofinal by \Cref{lem:Cofinality_Posets}: for $p \in P$, the subset $\{(Q,q) \mid p \leq q\}$ is non-empty, and it is filtered since two elements $(Q,q),(Q',q')$ are bounded by $(Q'',q'')$ where $q''$ is an upper bound of $q,q'$ and $Q'' \in \Sigma$ contains $Q \cup Q' \cup \{q''\}$. Hence $\colim_P F \simeq \colim_E F\rho \simeq \colim_{\Sigma} \pi_!(F\rho)$, where $\pi_!$ denotes left Kan extension along $\pi$. All indexing categories in this calculation are filtered, so the assumed filtered colimits suffice. For $Q \in \Sigma$ we have $\pi_!(F\rho)(Q) = \colim_{(Q',q') \in E,\, Q' \subseteq Q} F(q')$, and the map $Q \to \{(Q',q') \in E \mid Q' \subseteq Q\}$, $q \mapsto (Q,q)$, is cofinal by \Cref{lem:Cofinality_Posets}: for $(Q',q')$ with $Q' \subseteq Q$, the subset $\{q \in Q \mid q' \leq q\}$ is non-empty and filtered. Hence $\pi_!(F\rho)(Q) \simeq \colim_{q \in Q} F(q)$, which proves the claim.
	\end{proof}

claims.statement:
\begin{remark}
		\label[remark]{rem:Sequential_Diagrams}
		Since the nerve of $\N$ contains the simplicial subset $\bigcup_n \Delta^{\{n,n+1\}}$ via an inner anodyne map, a functor $\N \to D$ amounts to a sequence of objects and morphisms $x_0 \to x_1 \to x_2 \to \dots$ in $D$, without further coherence data. Similarly, since $\Delta^1 \times \bigcup_n \Delta^{\{n,n+1\}} \subseteq \Delta^1 \times \N$ is inner anodyne \cite[Corollary~2.3.2.4]{lurie2009HTT}, a natural transformation $\eta\colon x_{\bullet} \to x'_{\bullet}$ of sequences amounts to morphisms $\eta_n\colon x_n \to x'_n$ together with homotopies witnessing the commutativity of each square
		\[
			\begin{tikzcd}
				x_n \rar \dar["\eta_n"'] & x_{n+1} \dar["\eta_{n+1}"] \\
				x'_n \rar & x'_{n+1}.
			\end{tikzcd}
		\]
		We will use this freely.
	\end{remark}

proofs.text:
\begin{proof}
		Consider the sequence $Y \xrightarrow{r} X \xrightarrow{s} Y \xrightarrow{r} X \xrightarrow{s} \dots$. The maps $\N \to \N$ given by $n \mapsto 2n$ and $n \mapsto 2n+1$ are cofinal by \Cref{lem:Cofinality_Posets}. Restricting along the first gives the sequence $Y \xrightarrow{e} Y \xrightarrow{e} \dots$, and restricting along the second gives a sequence $X \to X \to \dots$ all of whose maps are equivalences $rs \simeq \id_X$; the colimit of the latter is $X$. Hence both colimits agree with the colimit of the interleaved sequence.
	\end{proof}

claims.statement:
\begin{proposition}
		\label[proposition]{prop:Omega_1_Compact_In_Ind}
		Let $C$ be a small category and let $X \in \Ind(C)$. Then $X$ is $\omega_1$-compact if and only if $X \simeq \colim_n y(c_n)$ for some sequence $c_0 \to c_1 \to c_2 \to \dots$ in $C$.
	\end{proposition}

\begin{definition}
		\label[definition]{def:Ind_Kappa}
		For a small category $C_0$, we let $\Ind_{\kappa}(C_0) \subseteq \PSh(C_0)$ denote the full subcategory spanned by the $\kappa$-filtered colimits of representable presheaves. We write $\Ind = \Ind_{\omega}$.
	\end{definition}

\begin{theorem}[{\cite[Section~5.3.5]{lurie2009HTT}}]
		\label[theorem]{thm:Ind_Kappa_Universal_Property}
		Let $C_0$ be a small category.
		\begin{enumerate}
			\item The category $\Ind_{\kappa}(C_0)$ admits $\kappa$-filtered colimits, computed in $\PSh(C_0)$, and the Yoneda embedding $y\colon C_0 \hookrightarrow \Ind_{\kappa}(C_0)$ lands in $\kappa$-compact objects.
			\item For every category $D$ admitting $\kappa$-filtered colimits, restriction along $y$ induces an equivalence between the category of functors $\Ind_{\kappa}(C_0) \to D$ preserving $\kappa$-filtered colimits and $\Fun(C_0,D)$. The inverse is given by left Kan extension along $y$.
			\item If $C_0$ admits $\kappa$-small colimits, then $\Ind_{\kappa}(C_0)$ admits all small colimits, $y$ preserves $\kappa$-small colimits, and for every category $D$ admitting small colimits, restriction along $y$ induces an equivalence between colimit-preserving functors $\Ind_{\kappa}(C_0) \to D$ and functors $C_0 \to D$ preserving $\kappa$-small colimits.
		\end{enumerate}
		\ifdefined\HCode
			For the equivalence in (3) when $D$ is $\kappa$-presentable, see \href{https://animarium.org/tag/1117/}{[SCT, Proposition~17.3.5]}.
		\fi
	\end{theorem}

\begin{definition}
		\label[definition]{def:Accessible}
		A category $C$ is \emph{$\kappa$-accessible} if it is locally small, admits $\kappa$-filtered colimits, the full subcategory $C^{\kappa}$ is essentially small, and every object of $C$ is a $\kappa$-filtered colimit of $\kappa$-compact objects. It is \emph{accessible} if it is $\kappa$-accessible for some $\kappa$. A functor between accessible categories is \emph{accessible} if it preserves $\kappa$-filtered colimits for some $\kappa$. A category is \emph{presentable} if it is accessible and admits all small colimits.
	\end{definition}

\begin{theorem}[{\cite[Section~5.4.2]{lurie2009HTT}}]
		\label[theorem]{thm:Accessible_Recollections}
		\leavevmode
		\begin{enumerate}
			\item A category $C$ is $\kappa$-accessible if and only if $C \simeq \Ind_{\kappa}(C_0)$ for some small category $C_0$. In this case, the inclusion $C^{\kappa} \subseteq C$ induces an equivalence $\Ind_{\kappa}(C^{\kappa}) \simeq C$, and $C^{\kappa}$ is the idempotent completion of $C_0$.
			\item If $C$ is $\kappa$-accessible, then $C^{\lambda}$ is essentially small for every regular cardinal $\lambda$, and $C$ is $\lambda$-accessible for arbitrarily large $\lambda$.
		\end{enumerate}
	\end{theorem}

\begin{theorem}[{\cite[Proposition~5.4.7.3]{lurie2009HTT}}]
		\label[theorem]{thm:Limits_Of_Accessible_Categories}
		The subcategory $\mathrm{Acc} \subseteq \widehat{\Cat}$ of accessible categories and accessible functors admits small limits, and the inclusion $\mathrm{Acc} \subseteq \widehat{\Cat}$ preserves them.
	\end{theorem}

\begin{lemma}
		\label[lemma]{lem:Accessible_Objects_Lambda_Compact}
		Let $C$ be an accessible category. Then every object of $C$ is $\lambda$-compact for some regular cardinal $\lambda$. Consequently, $C = \bigcup_{\lambda} C^{\lambda}$, where each $C^{\lambda}$ is essentially small.
	\end{lemma}

proofs.text:
\begin{proof}
		Let $C$ be $\kappa$-accessible and $x \in C$. Write $x = \colim_{i \in I} x_i$ with $I$ small and $\kappa$-filtered and each $x_i$ $\kappa$-compact. Choose a regular cardinal $\lambda \geq \kappa$ such that $I$ is $\lambda$-small. Each $x_i$ is $\lambda$-compact by \Cref{cor:Kappa_Small_Colimits_Of_Kappa_Compacts}(1). Moreover $\Map(x,-) \simeq \lim_{i \in I\catop}\Map(x_i,-)$ is a $\lambda$-small limit of functors preserving $\lambda$-filtered colimits, hence preserves them by \Cref{thm:Filtered_Colimits_Commute_With_Small_Limits}. The last statement follows from \Cref{thm:Accessible_Recollections}(2).
	\end{proof}

claims.statement:
\begin{lemma}
		\label[lemma]{lem:Retract_Left_Adjoint}
		Let $g\colon C \to D$ be a retract of $g'\colon C' \to D'$ in $\Fun(\Delta^1,\widehat{\Cat})$, where $C,C',D,D'$ are locally small. Suppose that $g'$ has a left adjoint $f'$ and that $C$ is idempotent complete. Then $g$ has a left adjoint.
	\end{lemma}

\begin{lemma}[Conjugate transformations]
		\label[lemma]{lem:Conjugate_Transformations}
		Let $F_1 \dashv G_1$ and $F_2 \dashv G_2$ be adjunctions between categories $A$ and $B$, with $F_i\colon A \to B$. For every natural transformation $\phi\colon F_1 \to F_2$ there is a unique natural transformation $\phi^{\vee}\colon G_2 \to G_1$, its \emph{conjugate}, such that the square
		\[
			\begin{tikzcd}
				\Map_B(F_2a,b) \rar["\phi^*"] \dar["\simeq"'] & \Map_B(F_1a,b) \dar["\simeq"] \\
				\Map_A(a,G_2b) \rar["(\phi^{\vee})_*"] & \Map_A(a,G_1b)
			\end{tikzcd}
		\]
		commutes naturally in $a$ and $b$. Moreover, $\phi$ is an isomorphism if and only if $\phi^{\vee}$ is.
	\end{lemma}

proofs.text:
\begin{proof}
		The composite of the top map with the vertical isomorphisms is a natural transformation $\Map_A(-,G_2(-)) \to \Map_A(-,G_1(-))$, which by the Yoneda lemma is induced by a unique natural transformation $\phi^{\vee}\colon G_2 \to G_1$. Again by the Yoneda lemma, $\phi$ is an isomorphism if and only if $\phi^*$ is an isomorphism for all $a,b$, if and only if $(\phi^{\vee})_*$ is an isomorphism for all $a,b$, if and only if $\phi^{\vee}$ is an isomorphism.
	\end{proof}

claims.statement:
\begin{lemma}[{\cite[Section~2.2, Propositions~2.1 and~2.2]{KellyStreet1974Mates}}]
		\label[lemma]{lem:Mates_Conjugates}
		In the situation of \Cref{constr:Mates}, assume that $G,G'$ admit left adjoints $F,F'$ and that $U,V$ admit right adjoints $U^R,V^R$. Then the mate $\beta\colon F'V \to UF$ (a transformation between left adjoints of $V^RG'$ and $GU^R$) is conjugate to the vertical mate $\gamma\colon GU^R \to V^RG'$. In particular, $\beta$ is an isomorphism if and only if $\gamma$ is.
	\end{lemma}

\begin{lemma}[Adjoint triples]
		\label[lemma]{lem:Adjoint_Triples}
		Let $F \dashv G \dashv H$ be an adjoint triple, with $F,H\colon A \to B$ and $G\colon B \to A$. Then $F$ is fully faithful if and only if $H$ is fully faithful.
	\end{lemma}

proofs.text:
\begin{proof}
		We have adjunctions $GF \dashv GH$ and $\id_A \dashv \id_A$. The unit $\eta\colon \id_A \to GF$ of $F \dashv G$ is a transformation between the left adjoints, and its conjugate is the counit $\varepsilon\colon GH \to \id_A$ of $G \dashv H$: indeed, under the identifications $\Map_A(GFa,a') \simeq \Map_B(Fa,Ha') \simeq \Map_A(a,GHa')$, precomposition with $\eta_a$ corresponds to postcomposition with $\varepsilon_{a'}$, by the triangle identities. Now $F$ is fully faithful if and only if $\eta$ is an isomorphism, and $H$ is fully faithful if and only if $\varepsilon$ is an isomorphism, so the claim follows from \Cref{lem:Conjugate_Transformations}.
	\end{proof}

claims.statement:
\begin{proposition}
		\label[proposition]{prop:Strongly_Continuous_Via_Right_Adjoint}
		Let $C$ and $D$ be compactly assembled categories, with left adjoints $\hat{y}_C$ and $\hat{y}_D$ of the colimit functors, and let $f\colon C \to D$ be a functor with a right adjoint $g$. Then the mate
		\[
			\beta\colon \hat{y}_D f \to \Ind(f)\hat{y}_C
		\]
		of the commutative square $\colim_D \circ \Ind(f) \simeq f \circ \colim_C$ is an isomorphism if and only if $g$ preserves filtered colimits.
	\end{proposition}

\begin{remark}
		\label[remark]{rem:Tensor_Product_Description}
		The second description arises as follows: one first shows that $\Fun^{\lim}(C\catop,D)$ is presentable, and then one computes that
		\[
			\Fun^{\colim}(\Fun^{\lim}(C\catop,D),E) \simeq \Fun^{\colim}(C,\Fun^{\colim}(D,E))
		\]
		for every presentable $E$.
	\end{remark}

\begin{corollary}
		\label[corollary]{cor:Ind_As_Exact_Functors}
		For a small stable category $A$, the restricted Yoneda functor induces an equivalence $\Ind(A) \simeq \Fun^{\ex}(A\catop,\Sp)$.
	\end{corollary}

proofs.text:
\begin{proof}
		Apply \Cref{prop:Tensor_With_Ind} with $D = \Sp$, using that $\Ind(A) \otimes \Sp \simeq \Ind(A)$ since $\Ind(A)$ is stable.
	\end{proof}

\begin{proof}
		We use the criterion \cite[Section~``Symmetric monoidal duality'']{Cnossen_StableHomotopy}: an object $X$ of a closed symmetric monoidal category is dualizable if and only if for every $Z$ the canonical map $Z \otimes \iHom(X,\unit) \to \iHom(X,Z)$, adjoint to $Z \otimes \iHom(X,\unit) \otimes X \xrightarrow{\id \otimes \ev} Z$, is an equivalence. For $X = \Ind(C_0)$ we have $\iHom(X,Z) = \Fun^{\colim}(\Ind(C_0),Z) \simeq \Fun^{\ex}(C_0,Z)$ by \Cref{thm:Ind_Kappa_Universal_Property}(3), and in particular $\iHom(X,\Sp) \simeq \Fun^{\ex}(C_0,\Sp) \simeq \Ind(C_0\catop)$ by \Cref{cor:Ind_As_Exact_Functors}. Under these identifications, $\ev\colon \Ind(C_0\catop) \otimes \Ind(C_0) \to \Sp$ is the colimit-preserving functor restricting on $C_0\catop \times C_0$ to $(a,c) \mapsto \hom_{C_0}(a,c)$, and the canonical map $Z \otimes \Ind(C_0\catop) \to \Fun^{\ex}(C_0,Z)$ agrees with the equivalence of \Cref{prop:Tensor_With_Ind}. Indeed, both are colimit-preserving functors out of $Z \otimes \Ind(C_0\catop)$, hence determined by their restrictions to $Z \times C_0\catop$ by \Cref{thm:Lurie_Tensor_Product} and \Cref{thm:Ind_Kappa_Universal_Property}(3); the canonical map sends $(z,a)$ to $z \otimes \ev(a,-) = z \otimes \hom_{C_0}(a,-)$, and so does the equivalence of \Cref{prop:Tensor_With_Ind}, since the equivalence $C \otimes D \simeq \Fun^{\lim}(C\catop,D)$ of \Cref{thm:Lurie_Tensor_Product} sends an elementary tensor $c \otimes d$ to the functor $c' \mapsto \Map_C(c',c) \otimes d$ \cite[Proof of Proposition~4.8.1.17]{lurie2016HA}.
		Hence $X$ is dualizable with dual $\Ind(C_0\catop)$ and evaluation as stated. The coevaluation corresponds, under $\iHom(X,X) \simeq X \otimes X^{\vee}$, to the identity of $X$, which under $\Fun^{\colim}(\Ind(C_0),\Ind(C_0)) \simeq \Fun^{\ex}(C_0,\Ind(C_0))$ corresponds to the Yoneda embedding.
	\end{proof}

